update content_bodies set title = '【沖縄旅行】梅雨でもおすすめ？５月の沖縄を満喫しよう！', description = 'この動画では、沖縄県への旅行や観光に役立つ情報を提供し、5月に楽しめるスポットを紹介しています。動画で紹介されていないおすすめの場所があれば、コメント欄でシェアするよう呼びかけています。『旅行の達人』チャンネルは、観光、移動、宿泊、食事などの旅行情報を発信し、旅行をより楽しくすることを目指しています。5月の梅雨の様子や、沖縄のハーリー祭り、花の見頃、旬の食材が楽しめる市場、雨の日でも安心な観光スポットについても触れています。' where id = 'Rwc5VSchyplT3_7fNk7Q1';
