update content_bodies set title = '徳島観光で外せない！日本百景「鳴門海峡と渦潮」の魅力', description = 'この動画は、徳島県への旅行を考えている方に向けて、鳴門海峡の魅力を5つ紹介しています。視聴者には、他のおすすめスポットをコメントでシェアするよう呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。旅行を通じて人生を豊かにすることがミッションであり、自己発見を促すことを重視しています。動画では、鳴門海峡の場所やアクセス、渦潮の説明、さまざまな展望台や大塚国際美術館などの観光スポットが紹介されています。訪問前には公式サイトで最新情報を確認するようにとの注意もあります。' where id = 'yBvqzH05uy0iUZh7ONLdf';
update content_bodies set title = 'The Unmissable Charm of Naruto Strait and Whirlpools in Tokushima Prefecture', description = 'This video serves as a guide for travelers to Tokushima Prefecture, highlighting five key attractions of the Naruto Strait. It invites viewers to share additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing comprehensive information on sightseeing, transportation, accommodation, and dining. The mission is to enrich lives through travel, encouraging exploration and self-discovery. The video covers the location and access to the Naruto Strait, explains the phenomenon of whirlpools, and suggests various viewpoints and attractions, including the Otsuka Museum of Art. Viewers are reminded to check official sites for the latest information before visiting.' where id = 'Z8gO31kW9y5cSGAIoDmIZ';
update content_bodies set title = '伊勢神宮食べ歩き！　#おはらい町 木下茶園', description = '伊勢神宮を訪れた際には、明治時代から続くお茶屋の木下茶園に立ち寄ることをおすすめします。ここでは、伊勢茶を使った絶品スイーツが楽しめます。特に人気のメニューは「伊勢白玉もち」で、注文後に茹でられる白玉はあつあつでモチモチ。抹茶きな粉がたっぷりかかっており、甘さと苦味のバランスが絶妙です。また、「伊勢抹茶ラテ」は、注文ごとに点てられる本格的な抹茶で、抹茶本来の旨味と香りを堪能できます。詳細は公式サイトをご覧ください。' where id = 'w1tkeWK2WOAvFlCPhBKCQ';
update content_bodies set title = 'Ise Jingu Food Walk! Kinoshita Chaen', description = 'When visiting Ise Jingu, a must-stop is Kinoshita Chaen, a tea shop established in the Meiji era, offering exquisite Ise tea sweets. Their popular menu item, Ise Shiratama Mochi, features freshly boiled shiratama balls that are hot and chewy, topped with a generous amount of matcha soybean powder, providing a perfect balance of sweetness and bitterness. Another highlight is the Ise Matcha Latte, made authentically by brewing Ise matcha for each order, allowing you to fully enjoy its rich flavor and aroma. For more details, visit their website.' where id = 'NtxH9x3tERydP7-CVBsNj';
update content_bodies set title = '贅沢！濃厚スイーツ　#四日市ファクトリーカフェ', description = '四日市ファクトリーカフェでは、地元食材を使った豊富なメニューが楽しめます。特に人気なのは、目の前で絞り出されるモンブランです。細さ1ミリの繊細でふんわりとしたマロンクリームには、隠し味としてラム酒が加えられ、大人の味わいに仕上げられています。クリームの中にはバニラアイス、カスタード、サクサクのクランブルが入っており、仕上げにたっぷりと削った栗が振りかけられ、様々な食感を楽しむことができます。味はマロンとかぶせ茶の2種類で、10月から3月までの期間限定販売です。' where id = '3ALAZ3_c9yIrki1xEtAsj';
update content_bodies set title = 'Luxury! Rich Sweets at Yokkaichi Factory Cafe', description = 'Yokkaichi Factory Cafe offers a delightful menu featuring local ingredients, with a highlight being the Mont Blanc prepared right before your eyes. The cafe''s signature marron cream, delicately squeezed to a thickness of 1 mm, is infused with rum for a sophisticated flavor. Inside, you''ll find a combination of vanilla ice cream, custard, and crunchy crumble, topped generously with shaved chestnuts, allowing for a variety of textures. The cafe offers two flavors: marron and kabusecha, available for a limited time from October to March.' where id = 'by1PL_vrUWkRfKoImbSNr';
update content_bodies set title = '山梨旅行/お土産】おすすめ名物！山梨のおみやげ14選', description = 'この動画は、山梨県を訪れる際に参考になるお土産を14選紹介しています。山梨旅行の際には、ぜひ購入したいアイテムが揃っています。動画で紹介されていないおすすめがあれば、コメント欄でシェアしてください。また、旅行の達人チャンネルでは、観光、移動、宿泊、食事など、旅行をより楽しくするための情報を提供しています。旅行を通じて人生を豊かにすることを目指しており、視聴者が新しい可能性を発見する手助けをしています。' where id = '0Mb7kYs6GR4TmwNhz5slu';
