update content_bodies set title = '沖縄の定番観光スポット15選', description = 'この動画は沖縄県への旅行を計画している方々に向けて、沖縄の定番観光スポットを15か所紹介しています。動画で紹介されていないおすすめスポットがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、視聴者の旅行体験をより豊かにすることを目指しています。旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見することを奨励しています。最新情報や旅行のヒントを得るために、公式のSNSアカウントをフォローすることもできます。' where id = '7oBfCvq1w39q97vXALQDF';
update content_bodies set title = '15 Must-Visit Tourist Spots in Okinawa', description = 'This video serves as a guide for those planning to travel to Okinawa, presenting 15 essential tourist spots. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing various travel information, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities. For more updates and travel tips, you can follow their official social media accounts.' where id = '6hRiggpN1KmDr1OwgvnTM';
update content_bodies set title = '和倉温泉旅館9選', description = '和倉温泉は、石川県にある開湯1200年の歴史を持つ温泉地で、一羽のシラサギによって湯脈が発見されたと言い伝えられています。藩政時代には湯治場として人気を博し、現在でも多くの観光客に愛されています。のどかな七尾湾や能登島を眺めながら楽しめる足湯や、弁天崎源泉公園での手湯、約90度の高温源泉を利用して自分で温泉卵を作る体験など、訪れるだけでも楽しめる施設が充実しています。石川県の東の玄関口である和倉温泉でのおすすめ宿泊施設を紹介します。' where id = 'lnAZ9FbRKNDmOs2cBDCNt';
update content_bodies set title = '9 Recommended Ryokans in Wakura Onsen, Ishikawa', description = 'Wakura Onsen, a historic hot spring area in Ishikawa Prefecture, boasts a 1200-year history, said to have been discovered by a heron. Once popular during the feudal era for healing, it remains a sought-after destination today. Visitors can enjoy foot baths with views of the serene Nanao Bay and Noto Island, as well as unique experiences like hand baths at the Bentenzaki Gensen Park and making onsen eggs using the hot springs. This guide introduces recommended accommodations in Wakura Onsen, the eastern gateway to Ishikawa, perfect for travelers looking to explore this charming hot spring town.' where id = 'rgyG88iEzQZGxNJfgFKAE';
update content_bodies set title = '【石川 観光】 石川県能登半島の観光スポット10選', description = '石川県への旅行や観光に役立つ情報を提供します。能登半島は日本海に突き出た美しい地域で、自然がもたらす海の幸や山の幸が豊富です。能登の魅力に心を奪われること間違いなしです。今回は、訪れるべき素晴らしいスポットを10か所厳選してご紹介します。' where id = '7IG4SIsB0lXClElf6VCOO';
update content_bodies set title = 'Top 10 Tourist Spots in Noto Peninsula, Ishikawa', description = 'This guide is perfect for those planning a trip to Ishikawa. The Noto Peninsula, which juts out into the Sea of Japan, offers a wealth of natural beauty and delicious seafood and mountain produce. You are sure to be captivated by the charm of Noto. In this article, we introduce ten must-visit spots that showcase the best of this beautiful region.' where id = 'UTpD7qF8-4DakyUP9GhWA';
update content_bodies set title = '【石川 観光】金沢おでん10選！', description = '金沢は歴史と文化が色濃く残る街で、地元の名物料理「金沢おでん」が楽しめます。金沢おでんは、車麩や赤巻、ふかし、バイ貝、加賀野菜など独特の具材を使用し、年間を通じて味わえるのが特徴です。この記事では、金沢を訪れた際にぜひ立ち寄りたいおすすめの金沢おでんの名店10軒を紹介します。茶屋街や武家屋敷、お城、寺町などの観光スポットを巡りながら、金沢おでんを味わうことをお忘れなく。' where id = 'h8_tTQoYP-b0tJyOQ-8GB';
update content_bodies set title = 'Top 10 Kanazawa Oden!', description = 'Kanazawa, a city rich in history and culture, is known for its unique local dish, Kanazawa Oden. This dish features distinctive ingredients such as car-fried gluten, red rolls, steamed dishes, bay shell, and Kaga vegetables, making it a must-try when visiting the area. Kanazawa Oden can be enjoyed year-round, and this guide presents ten recommended restaurants where you can experience this local delicacy. Whether you''re exploring the tea districts, samurai houses, or temples, don''t miss the chance to savor Kanazawa Oden during your trip.' where id = 'fD4Z0hLCsllhokP1-hT7V';
update content_bodies set title = '【大阪 観光】難波格安ホテル7選！', description = 'このガイドは、大阪を訪れる旅行者のために作成されており、ミナミ地区の中心に位置する難波に焦点を当てています。難波駅周辺は、デパートや大型商業施設、飲食店街が集まる賑やかな商業エリアで、道頓堀や心斎橋筋商店街などの大阪の名所も近くにあります。朝から深夜まで人々で賑わうこの街で、予算を抑えた旅行を希望する方のために、難波周辺にある格安ホテルを7軒紹介しています。' where id = '9klxZMCIWe11lT0DWL8zO';
update content_bodies set title = '7 Affordable Hotels in Namba, Osaka for Tourists', description = 'This guide is designed for travelers visiting Osaka, focusing on Namba, a bustling commercial area in the heart of the Minami district. Namba Station is surrounded by department stores, large shopping facilities, and dining streets, making it a vibrant hub. Nearby attractions include Dotonbori and Shinsaibashi Shopping Street, which are iconic spots in Osaka, bustling with people from morning until late at night. The article presents a selection of seven budget hotels located around Namba, providing options for those looking to explore the area without overspending.' where id = 'VsVt5kwgpIpy02RPlQzho';
update content_bodies set title = '【石川 観光】石川県で泊まりたい旅館15選', description = '石川県への旅行を計画している方に向けたガイドです。特に金沢は観光スポットとして人気があり、美しい景観と美味しい海鮮料理で知られています。この記事では、金沢周辺で楽しめる海鮮丼に焦点を当て、手頃な価格でランチやディナーを楽しめるおすすめの人気店を紹介しています。金沢でぜひ試してほしい海鮮丼のスポットを15選ご案内し、訪問者が新鮮で美味しい食事を楽しめるようにしています。' where id = 'rvx7xnDIAJhnstTYllCAK';
update content_bodies set title = '15 Recommended Ryokans to Stay in Ishikawa', description = 'This guide is perfect for those planning a trip to Ishikawa, particularly the popular city of Kanazawa, known for its beautiful sights and delicious seafood. The focus is on the best seafood bowls available in the area, highlighting affordable and popular restaurants for lunch and dinner. The article presents a selection of 15 must-try seafood bowl spots in Kanazawa, ensuring visitors can enjoy fresh and tasty meals during their stay.' where id = '3-YodRHK-HKLswvL5j2m2';
update content_bodies set title = '群馬の観光 & デートスポット10選', description = '群馬県への旅行を計画している方に最適なガイドで、地元の人々が推薦するデートスポット10か所を紹介しています。各スポットは独自の魅力を持ち、カップルが愛を深めるのにぴったりの場所です。温泉や風光明媚な公園など、素晴らしい思い出を作るための背景を提供します。また、視聴者に旅行のヒントや情報を提供するためにチャンネル登録を促しており、旅行を通じて新しい可能性を発見する手助けをすることを目指しています。' where id = 'p1f8ReVgrfj6h8kgGoHxj';
update content_bodies set title = 'Top 10 Tourist and Date Spots in Gunma', description = 'This guide is perfect for those planning a trip to Gunma Prefecture, showcasing ten recommended date spots by locals. Each location offers a unique charm, making them ideal for couples looking to deepen their love. From hot springs to scenic parks, these spots provide a wonderful backdrop for memorable experiences together. The video also encourages viewers to subscribe for more travel tips and information, aiming to enrich their travel experiences. The channel, ''Travel Master,'' is dedicated to sharing various travel insights, helping people discover new possibilities through travel.' where id = '4Nspg0p3ftyUiPl6SCVtE';
update content_bodies set title = '【長崎 観光】 長崎の観光スポット！穴場10選', description = '長崎県への旅行や観光の参考になる動画で、異国情緒あふれる長崎の穴場観光スポットを紹介しています。歴史好きや自然を楽しみたい人にとっても満足できるスポットが揃っています。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。『旅行の達人』チャンネルは、観光、移動、宿泊、食事などの情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。' where id = 'M_r63ZMFqN8AIH3sCuA9y';
update content_bodies set title = 'Nagasaki Tourism: 10 Hidden Gems', description = 'This video serves as a guide for those traveling to Nagasaki Prefecture, showcasing a variety of hidden tourist spots that reflect the area''s unique foreign charm. Whether you''re a history enthusiast or someone who enjoys nature, there are attractions to satisfy all interests. If you have any recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing comprehensive information on sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = 'gsnfjxiibLgTeooemSYGl';
update content_bodies set title = '大桑城跡 | 「戦国のメインステージ岐阜」', description = '大桑城は、室町時代から戦国時代にかけて美濃国の守護土岐氏が築いた山城です。天文4年（1535年）には長良川の大洪水により、守護所が大きな被害を受け、土岐氏は大桑に守護所を移しました。その後、城と城下町が整備されました。天文12年（1543年）には、勢力を増していた斎藤道三との間で大きな戦いが起こり、大桑城は落城したと考えられています。' where id = '7EVTfDWaJTnZrQqVDxki-';
update content_bodies set title = 'Okawa Castle Ruins | The Main Stage of the Sengoku Period in Gifu', description = 'Okawa Castle, a mountain castle of the Toki clan, who held power in Mino Province during the Muromachi to Sengoku periods, was significantly affected by a major flood of the Nagara River in 1535. Following this disaster, the Toki clan relocated their stronghold to Okawa, where they developed the castle and its surrounding town. In 1543, a significant battle occurred between the Toki clan and the rising power of Saito Dosan, leading to the fall of Okawa Castle.' where id = 'KQRqFqT57Nw380Ve3HoJq';
update content_bodies set title = '小島城跡 | 「戦国のメインステージ岐阜」', description = '小島城跡は姉小路氏の三家の一つ、小島氏の居城であり、神原峠の峠道が通る交通の要衝に位置しています。この城は高原郷からの敵の侵入を警戒するために設けられました。姉小路氏城跡は、古川城跡、小島城跡、野口城跡、向小島城跡、小鷹利城跡の5つの城跡を指し、飛騨市古川町などに存在します。令和6年2月21日には、その歴史的価値が評価され、国史跡に指定されました。' where id = 'qSQnWzCI9jfx5hIkaIyzC';
update content_bodies set title = 'Kojima Castle Ruins | The Main Stage of the Sengoku Period in Gifu', description = 'Kojima Castle Ruins served as the residence of the Kojima clan, one of the three branches of the Anekoji clan. It is strategically located at a key transportation point along the Kambara Pass, which connects the Takahara and Kojima regions, allowing for surveillance against enemy incursions from Takahara. The Anekoji clan castle ruins refer to a group of five castle ruins, including Furukawa Castle, Kojima Castle, Noguchi Castle, Mukokojima Castle, and Kotakari Castle, located in areas such as Furukawa Town in Hida City. On February 21, 2024, its historical significance was recognized, and it was designated as a national historic site.' where id = 'KfC_mi9uag29FkPpdGz31';
update content_bodies set title = '大垣城 | 「戦国のメインステージ岐阜」', description = '大垣城は、1535年に美濃守護・土岐一族の宮川吉左衛門尉安定によって創建されたとされています。江戸時代の大垣城は、水堀を幾重にも巡らせた大規模な城郭であり、城郭絵図にもその姿が描かれています。関ケ原の戦いでは、西軍の石田三成の本拠地となり、その後、戸田氏が入城し、明治時代まで大垣藩十万石を治めました。' where id = 'Q-aOuTArq1ify_AgWyWdi';
update content_bodies set title = 'Ogaki Castle: The Main Stage of the Sengoku Period in Gifu', description = 'Ogaki Castle was reportedly founded in 1535 by Miyakawa Yoshizaemon-no-Suji Yasunobu of the Toki clan, who served as the guardian of Mino. During the Edo period, Ogaki Castle was a large fortress surrounded by multiple moats, as depicted in castle maps. It served as the stronghold for Ishida Mitsunari of the Western Army during the Battle of Sekigahara. Later, the Toda clan took control of the castle and governed the Ogaki domain, which was worth 100,000 koku, until the Meiji period.' where id = 'ZOaCwNAR6IVsDq7hsuntF';
update content_bodies set title = '【ニセコ】紅葉が素晴らしい！地元民おすすめ！秋のニセコの魅力を紹介！', description = '北海道ニセコのおすすめスポットを紹介するチャンネルです。今回は、ニセコの最高級コテージを紹介し、複数人での宿泊やワーケーションに最適な施設を提案しています。秋の観光スポットや楽しみ方を紹介し、子供向けのイベントもあるため、旅行の参考にしてほしいとのことです。紅葉トレッキングやハロウィン、E-Bikeレンタル、英語キッズキャンプなど、秋の魅力を存分に楽しめる情報が満載です。このチャンネルは倶知安観光協会が運営しており、ニセコエリアの魅力を広めています。' where id = '30Lsm2-3rJtRyHEA5jPYJ';
update content_bodies set title = 'Niseko: Stunning Autumn Foliage! Local Recommendations! Discover the Charm of Autumn in Niseko!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. In this episode, we showcase some of the finest cottages in Niseko, perfect for group stays and ideal for workations. We invite you to come and experience the beauty of autumn in Niseko! The official SNS of the Kutchan Tourism Association shares insights on autumn attractions and activities for visitors, including events for children. Explore the beauty of autumn foliage, Halloween festivities, and various activities like E-Bike rentals and an English kids'' camp. This channel is operated by the Kutchan Tourism Association, dedicated to promoting the Niseko area.' where id = '1P3_e3RNJwoeLtzJ1wk0G';
update content_bodies set title = '岐阜城 | 戦国のメインステージ岐阜', description = '岐阜城は金華山の頂上に位置し、初めて砦を築いたのは鎌倉幕府に仕えた二階堂山城守行政とされています。戦国時代には斎藤道三公の居城でもありました。岐阜城が天下に名を知らしめたのは、1567年8月に織田信長公がこの城を攻略し、地名を「井口」から「岐阜」に改称し、天下統一の拠点としたことからです。' where id = 'VoMNK7AbTYVRKdXeL2o0U';
update content_bodies set title = 'Gifu Castle: The Main Stage of the Warring States Period', description = 'Gifu Castle, located on the summit of Kinka Mountain, was first established as a fort by Nikaido Yamashiro no Kami Yoshinari, who served the Kamakura Shogunate. During the Warring States period, it was also the residence of Saito Dosan. The castle gained prominence when Oda Nobunaga captured it in August 1567, renaming the area from ''Iguchi'' to ''Gifu'' and making it the base for his quest for national unification.' where id = 'Z14UaClfB6eWc6YtK3nfd';
update content_bodies set title = '岩村城跡 | 「戦国のメインステージ岐阜」', description = '岩村城は、奈良県の高取城、岡山県の松山城と並び、日本三大山城の一つに数えられ、また日本100名城にも選定されています。この城は、江戸時代の諸藩の府城の中で最も高い717mの標高に築かれ、高低差180mの険しい地形を巧みに利用した要害堅固な山城です。霧が発生しやすい気象条件も城の建設に活かされ、別名「霧ヶ城」とも呼ばれています。' where id = 'xQfSFIzVZCAhzHpGlcAQP';
update content_bodies set title = 'Iwamura Castle Ruins | The Main Stage of the Sengoku Period in Gifu', description = 'Iwamura Castle is one of Japan''s three great mountain castles, alongside Takatori Castle in Nara and Matsuyama Castle in Okayama. It is also designated as one of Japan''s 100 Famous Castles. The castle is built at the highest elevation among the Edo period''s provincial castles, standing at 717 meters above sea level, and it cleverly utilizes the steep terrain with a height difference of 180 meters, making it a formidable mountain fortress. The castle''s construction takes advantage of the foggy weather in the area, earning it the nickname ''Kiri no Shiro'' or ''Castle of Fog.''' where id = 'FXL36Y4JeI9VYgMw8OvDb';
update content_bodies set title = '【ドローン映像】菩提山城跡 | 「戦国のメインステージ岐阜」', description = '永禄元年（1558年）、この地で権力を持っていた岩手氏を竹中重元と息子・重治（半兵衛）が攻め落とし、翌年菩提山に城を築いたとされています。菩提山城は、竪堀や高低差の大きい堀切が複雑に組み合わさった大規模な山城です。塁はすべて土塁であり、石塁が見られないのが特徴で、最も完成型に近い土塁による城郭といわれています。' where id = 'cgB3Lt7KYSynwd6hS8jEx';
update content_bodies set title = 'Bodaizan Castle Ruins: The Main Stage of the Sengoku Period in Gifu', description = 'In 1558, the Iwate clan, who held power in this area, was attacked and defeated by Takenaka Shigeharu and his son Shigeharu (Hanbei). The following year, they built Bodaizan Castle. This large mountain castle features a complex design with vertical trenches and significant elevation differences. All ramparts are made of earthen mounds, with no stone walls present, making it one of the most complete examples of an earthen castle structure.' where id = 'F7ET_qIJBUhod9qHHlw3X';
update content_bodies set title = '【ドローン映像】苗木城跡 | 「戦国のメインステージ岐阜」', description = '苗木城は、1526年頃に苗木遠山氏によって築かれた城で、戦国時代の重要な遺構です。天然の巨石を利用した石垣は全国的に珍しく、大矢倉などでは岩を抱えるように積まれた石垣を見ることができます。また、時代によって異なる技法で石垣が積まれている点も特徴的で、続日本100名城にも選ばれています。' where id = 'lpK8wND3ldAp114cFRmYN';
update content_bodies set title = 'Drone Footage of Naegi Castle Ruins | The Main Stage of the Sengoku Period in Gifu', description = 'Naegi Castle was built around 1526 by the Naegi Toyama clan during the Sengoku period. The stone walls, constructed using natural giant rocks, are quite rare in Japan. At locations like the Oya-gura, visitors can see stone walls stacked in a way that embraces the rocks. Another notable feature is the different techniques used for stacking the stone walls across various periods. Naegi Castle is also recognized as one of the Continued Japan''s 100 Famous Castles.' where id = 'uBzJbbQ92QjpBhn3M47QJ';
update content_bodies set title = '【ドローン映像】美濃金山城跡 | 「戦国のメインステージ岐阜」', description = '美濃金山城は、可児市の古城山山頂に1537年に斎藤正義によって築城され、その後森可成が信長から城を賜り金山城に改称されました。約35年間、森氏の居城として利用されました。美濃金山城跡は、約400年前の石垣が当時の姿のまま残されており、戦国時代の息づかいを感じることができる貴重な場所です。平成25年には国史跡に指定され、続日本100名城にも選ばれています。' where id = '5wAGix-hDLXWUrdFI6-mU';
update content_bodies set title = 'Drone Footage of Minokanayama Castle Ruins | The Main Stage of the Warring States in Gifu', description = 'Minokanayama Castle, originally known as Karasuhō Castle, was built in 1537 by Saito Masayoshi, the adopted son of Dosan, on the summit of Kōjōyama in Kani City, which boasts one of the best views in the area. Later, it was granted to Mori Kanetaka by Nobunaga and renamed Kanayama Castle, serving as the residence of the Mori clan for about 35 years. The ruins of Minokanayama Castle feature stone walls that have remained intact for approximately 400 years, allowing visitors to experience the atmosphere of the Warring States period. In 2013, it was designated as a national historic site and selected as one of the Continued 100 Famous Castles of Japan.' where id = '4FRgDRuo6HTsXcUHnj2pR';
update content_bodies set title = '「Perfect G」【関の刃物編】', description = '岐阜県は、世界遺産の白川郷や下呂温泉、飛騨高山、長良川の鵜飼など、多くの観光地があり、毎年多くの観光客が訪れています。「Perfect G」は、岐阜県の魅力をユニークな視点で紹介することを目的としています。この「関の刃物編」では、岐阜の名産である刃物に焦点を当てています。岐阜県の観光情報については、岐阜県観光公式サイト「岐阜の旅ガイド」をご覧ください。' where id = 'qLrXpeFaK0AKfJhtC_oXk';
update content_bodies set title = 'Perfect G: Seki''s Blades', description = 'Gifu Prefecture is home to numerous tourist attractions, including the UNESCO World Heritage site Shirakawa-go, Gero Onsen, Takayama, and the cormorant fishing on the Nagara River, attracting many visitors each year. The aim of ''Perfect G'' is to deepen the understanding of Gifu''s charm through a unique perspective. This edition focuses on Seki''s blades, a renowned craft of the region. For more information on Gifu''s tourism, visit the official Gifu Prefecture tourism site ''Gifu Travel Guide''.' where id = 'nPak5Onf_ECTnqGkOqFtc';
update content_bodies set title = '【ニセコの絶景】空から眺める大人気スノーリゾート　Niseko Sky View', description = '北海道ニセコのおすすめスポットを紹介するチャンネルです。今回は、美しい冬のニセコの絶景をお届けします。ニセコの中心地であるひらふの空撮映像を楽しみながら、爽やかな音楽に合わせてゲレンデへ向かう車の流れを眺めて、リラックスしたひとときを過ごしてください。ぜひ冬のニセコに遊びに来てください！' where id = '4bafjh0pr2ZUKQvCoIzB3';
update content_bodies set title = 'Niseko Sky View: A Stunning Snow Resort from Above', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. In this episode, we showcase the breathtaking winter scenery of Niseko. Enjoy aerial footage of Hirafu, the heart of Niseko, as you relax to refreshing music while watching the flow of cars heading towards the ski slopes. We invite you to visit Niseko this winter!' where id = 'ZrbToqOlm7OdigkVhKz8H';
update content_bodies set title = '【NISEKOくっちゃん】SUPでリフレッシュ！ウォーターアクティビティが充実！', description = '北海道ニセコの倶知安観光協会が運営するこのチャンネルでは、日本有数のリゾート地であるニセコのおすすめスポットを紹介しています。夏には、尻別川や近くの洞爺湖でのSUPなど、さまざまなウォーターアクティビティが楽しめます。観光協会の公式SNSやホームページも紹介されており、地域の魅力を発信しています。' where id = '0erok237BMqkqewuu6gB-';
update content_bodies set title = 'Refresh with SUP in NISEKO Kutchan! Abundant Water Activities!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. During summer, various water activities are available, including refreshing Stand-Up Paddleboarding (SUP) on the Shiribetsu River and nearby Lake Toya. The channel is operated by the Kutchan Tourism Association, which provides information on local attractions and activities.' where id = 'A78IGDuCnzbnwGXBLxI5b';
update content_bodies set title = '【NISEKOくっちゃん】釣り', description = 'このチャンネルでは、北海道ニセコの倶知安観光協会が運営し、日本有数のリゾート地であるニセコのおすすめスポットを紹介しています。特に尻別川での釣りなど、自然の美しさやアクティビティを楽しむ情報を提供しています。観光やワーケーションの機会を促進し、ニセコの魅力を広めることを目的としています。' where id = 'fBQAuEI5sI25tlHsPNXty';
update content_bodies set title = 'Fishing in NISEKO Kutchan', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. It is operated by the Kutchan Tourism Association, which provides information about the beautiful landscapes and activities available in the region, including fishing in the Shiribetsu River. The channel aims to promote tourism and workation opportunities in Niseko, showcasing the area''s natural beauty and recreational options.' where id = 'l2OhbrZOkUsqauFUd9b4j';
update content_bodies set title = '【NISEKOくっちゃん】夏のアクティビティを紹介！大自然の中でアウトドアを満喫！', description = 'このチャンネルでは、北海道ニセコの倶知安観光協会が運営し、日本有数のリゾート地であるニセコのおすすめスポットを紹介しています。北海道の夏をアウトドアで楽しむための多彩なアクティビティが用意されており、自然の中での体験が満喫できます。倶知安観光協会の公式SNSやウェブサイトを通じて、最新情報やワーケーションの機会についても確認できます。' where id = 'RF-tTv5K4rQ5XfbLGAu-7';
update content_bodies set title = 'Introducing Summer Activities in NISEKO Kutchan! Enjoy Outdoor Adventures in Nature!', description = 'This channel showcases recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. Experience the great outdoors and enjoy a variety of activities during the summer in Hokkaido! The channel is operated by the Kutchan Tourism Association, which provides information on local attractions and activities. Follow their official social media accounts on Instagram and Twitter for updates, and visit their official website for more information on workation opportunities in Niseko.' where id = 'zrPG7MYvd_ucdKzAEy6el';
update content_bodies set title = '【NISEKOくっちゃん】夏はサイクリングを楽しもう！', description = '北海道ニセコの倶知安観光協会が運営するこのチャンネルでは、日本有数のリゾート地であるニセコのおすすめスポットを紹介しています。夏のニセコはサイクリングに最適で、マウンテンバイクも楽しめます。観光協会の公式SNSやホームページもあり、地域のアクティビティや観光情報を発信しています。' where id = 'qtii1VSNmu-rJ2xiB23rS';
update content_bodies set title = 'Enjoy Cycling in NISEKO Kutchan This Summer!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas. Summer in Niseko is perfect for cycling, including mountain biking. The channel is operated by the Kutchan Tourism Association, which provides information about activities and attractions in the area.' where id = 'zNka78p1neSFLTNxmWx3Q';
update content_bodies set title = '【NISEKOくっちゃん】夏はハイキングがおすすめ！初心者から上級者まで楽しめる！', description = 'このチャンネルでは、北海道ニセコの観光スポットを紹介しています。倶知安エリアには、初心者から上級者まで楽しめる山々が点在しており、夏には大自然の中でハイキングを楽しむことができます。倶知安観光協会が運営しており、公式SNSやホームページもあります。' where id = 'ZnBrk-RJai-qAYta3GR_Z';
update content_bodies set title = 'NISEKO Kutchan: Hiking Recommended in Summer! Enjoyable for Beginners to Advanced!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. The NISEKO Kutchan area features mountains suitable for hikers of all levels, from beginners to advanced. In summer, enjoy hiking amidst the great outdoors!' where id = 'y_dwiOiPIiUTSf74AHTn2';
update content_bodies set title = '【北海道ニセコ】大自然×英語キッズキャンプ お子様だけでも楽しめる！', description = '日本有数のリゾート地である北海道ニセコのおすすめスポットを紹介するチャンネルです。今回は、EdVentureニセコ英語キッズキャンプを紹介します。このキャンプでは、お子様が大自然の中でアウトドアを満喫しながら、英語を学ぶことができます。お子様だけでも楽しめるプログラムが用意されており、安全で楽しい環境での体験が提供されます。' where id = '3Fu31oFYvxg7SExGu5cWT';
update content_bodies set title = 'Niseko, Hokkaido: Nature and English Kids Camp - Fun for Kids!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas. This time, we present the EdVenture Niseko English Kids Camp, where children can enjoy outdoor activities in the beautiful nature of Hokkaido. The camp is designed for kids to have fun independently in a safe and engaging environment.' where id = 'YV6v43H9aVvKW0JLjb_cM';
update content_bodies set title = '【ワーケーション】北海道ニセコがオススメ！アウトドアサウナからのパウダースノーにダイブ！', description = 'このチャンネルは、北海道ニセコでのワーケーションを推奨するもので、倶知安観光協会が運営しています。今回の動画では『アウトドアサウナxワーケーション』を紹介し、自然を感じながらの仕事の魅力を伝えています。アウトドアサウナでリラックスした後、パウダースノーに飛び込む体験は格別です。また、ニセコは冬だけでなく夏も魅力的な観光地であることを伝えるためにチャンネルを開設しました。今後も動画をアップしていく予定で、チャンネル登録を歓迎しています。' where id = 'v4D0UruwKbifQQuyhqhpY';
update content_bodies set title = 'Recommended Workation in Niseko, Hokkaido! Dive into Powder Snow from an Outdoor Sauna!', description = 'This channel promotes workation opportunities in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The latest video introduces the concept of ''Outdoor Sauna x Workation,'' highlighting the unique experience of working while enjoying nature. Viewers can relax in an outdoor sauna and then dive into the powder snow, making for an exceptional work environment. The channel also emphasizes that Niseko is not only famous for winter activities but is also a great summer destination. The Kutchan Tourism Association aims to showcase the summer attractions of Niseko through this channel, with plans to upload more videos in the future. Subscriptions are welcomed!' where id = 'Ae0v12wWa14ynwE6NI5v5';
update content_bodies set title = '【NISEKOくっちゃん】ペイントボール体験！サバイバルゲームみたいなシューティングアクティビティ', description = 'このチャンネルでは、北海道ニセコにある倶知安観光協会が運営し、日本有数のリゾート地であるニセコのおすすめスポットを紹介しています。特にペイントボールフィールド・ニセコでは、サバイバルゲームのようなシューティングアクティビティを楽しむことができます。また、倶知安観光協会の公式SNSやホームページを通じて、地域の情報やワーケーションに関する情報も提供しています。' where id = 'WnqP4mU9G5wxpEGu9REN5';
update content_bodies set title = 'Paintball Experience in NISEKO! A Shooting Activity Like Survival Games', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. It features the Paintball Field Niseko, where visitors can enjoy an exciting paintball experience. The channel is operated by the Kutchan Tourism Association, which provides information about the area and promotes activities such as workation in Niseko. For more details, you can follow their official social media accounts on Instagram and Twitter, or visit their official website.' where id = 'j9a3J9-liReBVm6poOvwf';
update content_bodies set title = '【NISEKOくっちゃん】テントサウナを北海道の大自然の中で体験！', description = 'このチャンネルでは、日本有数のリゾート地である北海道ニセコのおすすめスポットを紹介しています。倶知安観光協会が運営しており、夏・冬ともに楽しめるテントサウナを大自然の中で体験できます。公式SNSやホームページもあり、最新情報をチェックできます。' where id = 'IfzsW4DwMKmpLg6w9y4m2';
update content_bodies set title = 'Experience Tent Sauna in the Great Nature of NISEKO, Hokkaido!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas. Experience tent sauna in the great nature of Hokkaido, available for enjoyment in both summer and winter! The channel is operated by the Kutchan Tourism Association, which provides information about the Kutchan area in the Niseko region. Follow their official social media for updates and more information.' where id = 'Pw-itgiriRWda3y-YDrYE';
update content_bodies set title = '【ワーケーション】北海道ニセコでワーケーションがオススメ！', description = 'このチャンネルでは、日本有数のリゾート地である北海道ニセコのおすすめスポットを紹介しています。東京MXのTV番組「ええじゃない課Biz」で取り上げられました。現在、冬の宿泊料金が公開中です。詳細はワーケーションニセコのウェブサイトをご覧ください。このチャンネルは、ニセコエリアの倶知安観光協会が運営しており、観光情報を提供しています。公式SNSのインスタグラムやTwitterもフォローして、最新情報をチェックしてください。' where id = '9ywjYOjDTKYvC6CeUWbJz';
update content_bodies set title = 'Recommended Workation in Niseko, Hokkaido!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas. It was featured on the Tokyo MX TV program ''Eejanai-ka Biz.'' Currently, winter accommodation rates are available! For more information, visit the Workation Niseko website. The channel is operated by the Kutchan Tourism Association, which provides insights into the Niseko area. Follow their official social media accounts on Instagram and Twitter for updates.' where id = 'FOl5rL_KGjLWxu0wluDdy';
update content_bodies set title = '【ニセコグルメ】日本最高級リゾートの本格イタリアン！を堪能！PARK HYATT NISEKO HANAZONO--オリヴィオ-', description = '北海道ニセコのおすすめスポットを紹介するチャンネルです。今回は、日本最高級リゾート『PARK HYATT NISEKO HANAZONO』内にある本格イタリアン『オリヴィオ』を紹介します。新鮮な野菜を使ったサラダ、豊富なバリエーションのパスタ、そして本場スタイルで焼き上げるピッツァが自慢です。ぜひ訪れて、その美味しさを堪能してみてください！' where id = 'f9fz6FqCMcLAQCQEk_NDS';
update content_bodies set title = 'Authentic Italian Cuisine at Japan''s Finest Resort! Experience PARK HYATT NISEKO HANAZONO - Olivio', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas. In this episode, we feature ''Olivio,'' an authentic Italian restaurant located in the luxurious ''PARK HYATT NISEKO HANAZONO.'' The restaurant specializes in fresh vegetable salads, a wide variety of pasta, and traditional pizzas baked in the authentic style. Be sure to visit and enjoy the exquisite dining experience!' where id = 'w1q3HCC2YXEXpP_ViD9R7';
update content_bodies set title = '【ニセコグルメ】日本最高級リゾートの絶品中華料理を紹介！！PARK HYATT NISEKO HANAZONO-チャイナキッチン-', description = '北海道ニセコのおすすめスポットを紹介するチャンネルです。日本最高級リゾート『PARK HYATT NISEKO HANAZONO』にある『チャイナキッチン』を紹介します。今回は週末限定の「飲茶ブランチ」を取り上げ、食べ放題で1人4,800円（5,280円）です。メニューの一部を紹介しましたが、他にもたくさんのメニューがあります。ぜひ足を運んで、絶品料理を堪能してみてはいかがでしょうか。' where id = '_t8KFYiewySjVtEW-NsoG';
update content_bodies set title = 'Introducing Exquisite Chinese Cuisine at Japan''s Finest Resort! PARK HYATT NISEKO HANAZONO - China Kitchen', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. We present ''China Kitchen'' at the luxurious ''PARK HYATT NISEKO HANAZONO.'' This time, we highlight the weekend-only ''Dim Sum Brunch,'' which offers an all-you-can-eat experience for 4,800 yen (5,280 yen). While we showcased a portion of the menu, there are many more dishes available. We encourage you to visit and enjoy the culinary delights!' where id = 'HmYnCe4VW18mc3yfJ7_uI';
update content_bodies set title = '紅葉ドライブ 新千歳空港〜北海道ニセコエリアまでのおすすめスポット！', description = 'このチャンネルでは、日本有数のリゾート地である北海道ニセコのおすすめスポットを紹介しています。今回は新千歳空港からニセコエリアまでのレンタカーを利用したおすすめスポットを紹介し、美味しいグルメや観光地がたくさんあることをお伝えします。季節によっては素晴らしい絶景も楽しめます。' where id = 'nkCBeTzSZ9_zp7xa8xW5x';
update content_bodies set title = 'Recommended Spots from New Chitose Airport to the Niseko Area for Autumn Drives!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas. In this episode, we highlight must-visit locations along the route from New Chitose Airport to the Niseko area, utilizing rental cars. There are plenty of delicious gourmet options and sightseeing spots to explore! Depending on the season, you can also enjoy breathtaking views.' where id = 'i0-DsQfwSFnrcpBVfcAC9';
update content_bodies set title = '【分散型旅行】北海道ニセコで秋を探しに行くよ！（紅葉vlog）＝半月湖＝ | ニセコサマーステイ（倶知安観光協会）', description = 'このvlogでは、北海道ニセコエリアの秋の美しさを紹介しています。のんびりドライブを楽しみながら、紅葉の美しいスポットを訪れる内容です。主に、紅葉を楽しむためのドライブと、半月湖という美しい場所での紅葉狩りが取り上げられています。撮影日は2020年10月12日で、自然の中での穏やかな秋の体験を強調しています。このチャンネルは倶知安観光協会が運営しており、地域の観光スポットを紹介し、旅行を促進しています。' where id = 'hYetoB9Ef6uiTfF5CKo-M';
update content_bodies set title = 'Exploring Autumn in Niseko, Hokkaido! (Autumn Leaves Vlog) = Hangetsuko = | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This vlog highlights the beauty of autumn in the Niseko area of Hokkaido, focusing on leisurely drives and stunning fall foliage. The video showcases two main segments: a scenic drive to enjoy the autumn leaves and a visit to Hangetsuko Lake, a picturesque spot for leaf viewing. Filmed on October 12, 2020, the content emphasizes the tranquil experience of exploring nature during the fall season. The Kutchan Tourism Association operates this channel, providing insights into local attractions and promoting travel in the region.' where id = 'rFwL4bHTfAIJwlC_5qEa9';
update content_bodies set title = '【ニセコグルメ】高級ホテルの絶品朝食ビュッフェ！【雲レストラン】', description = '北海道ニセコのおすすめスポットを紹介するチャンネルです。今回は『スカイニセコ』内の『雲レストラン』を紹介します。和食をベースに、新鮮な北海道産の食材にこだわったレストランです。ランチタイムにはハンバーガーやクロックムッシュなどのメニューがあり、ディナーは友人や家族と楽しめるシェアプレートメニューが中心です。コロナ対策として、10月31日までは宿泊人数に応じて、フルビュッフェからシェフが手作りした和食と洋食が選べる朝食セットスタイルに変更されています。' where id = '3EUL2KvlJXA4J0r2JkLVz';
update content_bodies set title = 'Delicious Breakfast Buffet at a Luxury Hotel in Niseko! [Kumo Restaurant]', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas. This time, we feature ''Kumo Restaurant'' located within ''Sky Niseko''. The restaurant focuses on Japanese cuisine, emphasizing fresh ingredients from Hokkaido. For lunch, the menu includes items like hamburgers and croque monsieur. Dinner offers share plates suitable for enjoying with friends and family. Due to COVID-19 measures, until October 31, the buffet style has been changed to a breakfast set style, where guests can choose from carefully prepared Japanese and Western dishes made by the chef.' where id = '-r7UYYapBiVLGCJbU68y_';
update content_bodies set title = '【北海道ニセコ】玄関口『倶知安（くっちゃん）駅』の近くをぶらり散歩。電車が来るまでの時間でのんびり満喫できるお店をご紹介します。', description = 'このチャンネルでは、日本有数のリゾート地である北海道ニセコのおすすめスポットを紹介しています。今回は、ニセコエリアの玄関口である倶知安駅周辺で、電車が来るまでの時間に楽しめるお店を紹介します。駅前食堂やお菓子のふじい、ROCO SANDなど、地元の魅力的な店舗が登場し、観光客が倶知安での時間を有意義に過ごすためのガイドとなっています。' where id = 'KUR6LG7RUUcgmy9zRlIT4';
update content_bodies set title = 'Strolling Around Kutchan Station, the Gateway to Niseko, Hokkaido: Enjoyable Shops to Visit While Waiting for the Train', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas. In this episode, we explore shops around Kutchan Station, the gateway to the Niseko area, where visitors can enjoy their time while waiting for the train. The video includes a variety of local establishments, such as eateries, sweet shops, and rental services, providing a glimpse into the vibrant community. Each segment highlights different shops, including ''Station Front Diner'', ''Fujii Confectionery'', ''ROCO SAND'', and more, making it a perfect guide for travelers looking to make the most of their time in Kutchan.' where id = 'y5e-0yy1dfM3zsUH9Vlm9';
update content_bodies set title = '【北海道ニセコ】子供と滞在中にのんびり！地元キッズが楽しさ保証！おすすめ４選！', description = 'このチャンネルでは、日本有数のリゾート地である北海道ニセコのおすすめスポットを紹介しています。今回は、滞在中に子供と一緒にのんびり過ごすための地元キッズに人気のスポットを紹介します。内容には、ホテルニセコアルペン、旭ヶ丘公園、わんぱく広場、どんぐり公園などが含まれ、車で40分以内の公園も紹介されています。各スポットには詳細と地図が提供されており、家族で楽しい時間を過ごすための情報が満載です。' where id = 'boG2W_fWYfTkTGQicmdPW';
update content_bodies set title = 'Niseko, Hokkaido: Relaxing with Kids! 4 Recommended Spots Guaranteed Fun by Local Kids!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s top resort areas. In this episode, we present local favorites for families looking to relax and enjoy time with their children during their stay. The video covers various locations, including Hotel Niseko Alpen, Asahigaoka Park, Wanpaku Square, and Donguri Park, along with other parks within a 40-minute drive. Each spot is highlighted with details and maps for easy navigation, ensuring a fun and enjoyable experience for families.' where id = 'rjMWnfXdVCWK_NhgwjzFv';
update content_bodies set title = '【ニセコ】人気家族スポット！野菜収穫からの石窯ピザ作り体験！【グリーンファーム】', description = '北海道ニセコのおすすめスポットを紹介するチャンネルです。今回は『Niseko Green Farm』での石窯ピザ作り体験を紹介します。体験は畑やハウスでの野菜収穫から始まり、収穫したての野菜の美味しさを味わえます。家族連れに人気のイベントで、体験料金は季節によって異なります。大人や子供の料金が設定されており、詳細はNiseko Green Farmの公式サイトで確認できます。' where id = 'gRNl15pG4Z-mucK_MTyGe';
update content_bodies set title = 'Niseko: A Popular Family Spot! Experience Vegetable Harvesting and Stone Oven Pizza Making! [Green Farm]', description = 'This channel introduces recommended spots in Niseko, one of Japan''s top resort areas. In this episode, we showcase the experience of making pizza in a stone oven at ''Niseko Green Farm.'' The adventure begins with harvesting fresh vegetables from the fields and greenhouses, allowing visitors to enjoy the delicious taste of freshly picked produce. This event is particularly popular among families. The experience is available at different prices depending on the season, with adults and children paying specific rates. For more information, visit the official website of Niseko Green Farm.' where id = 'ggl6CrUDeHDAOo_1bXByg';
update content_bodies set title = '【ワーケーション】北海道ニセコでワーケーション2021年最新情報', description = 'このチャンネルは、北海道ニセコエリアの倶知安観光協会が運営し、サマーステイを推奨しています。動画では、2021年のニセコでのワーケーションに関する最新情報を紹介し、5つの魅力を挙げています。1つ目は豊富な滞在型宿泊施設、2つ目は北海道の大自然、3つ目は美味しい食べ物、4つ目は周辺の距離感の良さ、5つ目は便利な田舎です。また、無料のシェアオフィスやレンタルオフィスの増加についても触れています。ニセコの夏の魅力を伝えるためにチャンネルを開設し、今後も動画をアップしていく予定です。' where id = 'pSA1nrPKMaxNB_9Oi8ZQv';
update content_bodies set title = 'Workation in Niseko, Hokkaido: Latest Information for 2021', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The video introduces the latest information on workation in Niseko for 2021, highlighting five attractions: 1) a variety of accommodation options, 2) the great natural environment of Hokkaido, 3) delicious food, 4) convenient distances to nearby attractions, and 5) the benefits of a rural setting. It also provides updates on free shared office spaces and the increasing availability of rental offices. The channel aims to showcase the summer charm of Niseko, encouraging viewers to subscribe for more content.' where id = 'Qz99sSMlAtZaB6rM52HIb';
update content_bodies set title = '【北海道グルメ】肉が絶賛！ニセコで絶対に行くべきお店を紹介！Black Wood Grill', description = '日本有数のリゾート地、北海道ニセコのおすすめスポットや飲食店を紹介するチャンネルです。今回は、倶知安町ヒラフエリアにある『Black Wood Grill』を紹介しました。地元の新鮮食材を使用した絶品料理が楽しめるお店です。ぜひ足を運んでみてください！動画は昨年12月に撮影されています。' where id = 'm_tNrjybX2RbCjnGgBXNf';
update content_bodies set title = 'Hokkaido Gourmet: Must-Visit Restaurant in Niseko - Black Wood Grill', description = 'This channel introduces recommended spots and dining options in Niseko, one of Japan''s top resort areas. In this episode, we feature ''Black Wood Grill'' located in the Hirafu area of Kutchan Town. The restaurant offers exquisite dishes made from fresh local ingredients. Be sure to visit! The video was filmed last December.' where id = '9hguvJ64tScgq-7E4a6gv';
update content_bodies set title = '【北海道ニセコ】ペンションあいらんどのご紹介', description = 'ペンション紹介シリーズ第7弾『早川さんと行く！ニセコのペンション詳しく知り隊』では、愛が詰まった暖かいペンション『ペンションあいらんど』を紹介します。動画では、ペンションの背景や始めた理由、お客様とのエピソード、客層、夏のおすすめ、部屋数、ニセコへの未来の思いなどが語られています。また、早川さんのおすすめポイントも紹介されています。撮影は2020年12月上旬に行われました。' where id = 'CgQyuUm1tB0W1hFTiJtfp';
update content_bodies set title = 'Introducing Pension Ailand in Niseko: A Pension Filled with Love', description = 'This is the seventh installment of the pension introduction series, ''Let''s Learn About Niseko''s Pension with Hayakawa-san!'' We introduce ''Pension Ailand,'' a warm pension filled with love. The video covers various aspects of the pension, including its background, the reason for starting the pension, customer stories, the types of guests, summer recommendations, the number of rooms, and future aspirations for Niseko. Hayakawa-san also shares personal recommendations. The filming took place in early December 2020.' where id = 'US5LY4EzDDumdzl9LMsKj';
update content_bodies set title = '【ニセコグルメ】地元民オススメ！お酒が豊富で食材にこだわったお店【大衆バルJAM】', description = '北海道ニセコのおすすめスポットを紹介するチャンネルです。今回は「大衆バルJAM」をご紹介します。このお店には、スペインで予約が取れない超有名店のシェフが在籍しており、料理の味は絶品です。美味しい食事を求めている方は、ぜひ訪れてみてください。' where id = '6T2ZlZHMClLm6YI6abqH7';
update content_bodies set title = 'Niseko Gourmet: Recommended by Locals! A Restaurant with Abundant Alcohol and Quality Ingredients - Taisyu Bar JAM', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas in Hokkaido. This time, we present ''Taisyu Bar JAM,'' where a chef from a highly acclaimed restaurant in Spain, known for being nearly impossible to book, is working. The taste of the dishes is exceptional! If you''re looking for delicious food, don''t hesitate to visit!' where id = '4cMV74DkP0VLTZ-XLMeWy';
update content_bodies set title = '【ニセコグルメ】3年連続で賞を獲得！本格的でオシャレなBarを紹介！【TOSHIRO''S BAR】', description = '北海道ニセコのおすすめスポットを紹介するチャンネルです。今回は、『BEST OF NISEKO AWARDS』で3年連続賞を受賞した「TOSHIRO''S BAR」をご紹介します。オシャレで美味しい本格的なお酒を楽しめる場所で、アルコールが苦手な方でも美味しいドリンクを堪能できます。TOSHIRO''S BARの公式Instagramや、倶知安観光協会のSNSもチェックして、ニセコエリアの魅力をさらに知ってください。' where id = 'B_jx7lTXDB9bbRu-nkAN2';
update content_bodies set title = 'Niseko Gourmet: Introducing TOSHIRO''S BAR, Awarded for Three Consecutive Years!', description = 'This channel introduces recommended spots in Niseko, one of Japan''s premier resort areas located in Hokkaido. In this episode, we feature ''TOSHIRO''S BAR,'' which has won the ''BEST OF NISEKO AWARDS'' for three consecutive years. Enjoy stylish and delicious authentic drinks, with options available for those who may not prefer alcohol. Follow TOSHIRO''S BAR on Instagram for more updates and check out the Kutchan Tourism Association''s official social media for additional information about the area.' where id = '1KhEC6rMBU0HQ9uQtPwGo';
update content_bodies set title = '北海道江別市公式観光PR動画', description = '夏の北海道江別市を紹介する公式観光PR動画が制作されました。この動画は、江別市の美しさや魅力を伝えるもので、Ezo Explorerによって監督されています。Ezo Explorerは、観光PR映像やトラベルビデオを専門とする北海道を拠点としたクリエイターチームです。出演者にはヒヌマフウフが登場し、江別市の公式InstagramやYouTubeで視聴可能です。制作にはSony α7siiiやDji AIR2Sなどの高品質な機材が使用され、シネマティックな体験を提供しています。動画制作に関する問い合わせは、Ezo Explorerのメールアドレスまでお願いします。' where id = 'Hd2ynAGJx-P_Pk3yCDqjY';
update content_bodies set title = 'Visit the Ebetsu Official Tourism PR Video', description = 'This is the official tourism PR video for Ebetsu City, Hokkaido, created during the summer. The video showcases the beauty and attractions of Ebetsu, directed by Ezo Explorer, a creator team based in Hokkaido that specializes in tourism promotion and travel videos. The video features the talents of Hinuma Fuu and is available on various social media platforms, including Instagram and YouTube. The production utilized high-quality gear such as the Sony α7siii and Dji AIR2S, ensuring a cinematic experience. For inquiries regarding video production, contact Ezo Explorer via email.' where id = 'UFUbCfScoAn7EQ61XE8_f';
update content_bodies set title = '【北海道ニセコ】ペンションご紹介⑥「ニューホワイトベア」創業40年老舗中の老舗！', description = 'このチャンネルは、北海道ニセコでのサマーステイをオススメするもので、倶知安観光協会が運営しています。ペンション紹介シリーズ第6弾として、創業40年の老舗『ニューホワイトベア』を紹介します。動画では、ペンションの概要やお客様の体験、オーナーの話、大変だったエピソード、スキーに関する話、ニセコへの想いなどが語られます。撮影場所はニューホワイトベアで、ニセコの夏の魅力を伝えるために動画を随時アップしていく予定ですので、チャンネル登録をお願いしています。' where id = 'MZyI9oxNLOE0yoQk4nFGx';
update content_bodies set title = 'Introducing Pension New White Bear in Niseko, Hokkaido - A Long-Established Inn Celebrating 40 Years!', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. In the sixth installment of the pension introduction series, we present ''New White Bear,'' a long-established inn. The video covers various topics including an overview of the pension, customer experiences, owner insights, challenges faced, skiing discussions, and the owner''s passion for Niseko. The filming location is New White Bear, and viewers are encouraged to subscribe for more videos showcasing the summer attractions of Niseko, which is famous for winter but also offers great summer experiences.' where id = '2YTmKx67lklfZXBHLlVH2';
update content_bodies set title = '【北海道ニセコ】ペンション香暖-カノン-のご紹介！蟹好き必見！', description = 'このチャンネルは、北海道ニセコでのサマーステイを推奨する倶知安観光協会が運営しています。ペンション紹介シリーズ第5弾では、蟹好きにぴったりの『ペンション香暖-カノン-』を紹介します。動画では、ペンションの概要、ニセコ育ちのオーナー、レストランの詳細、蟹のおすすめの食べ方、レストランのお客様について、ニセコでの過ごし方の提案などが紹介されます。撮影場所はペンション香暖で、ニセコの夏の魅力を伝えるために、今後も動画をアップしていく予定ですので、チャンネル登録をお勧めします。' where id = 'PQlEWC5J1fhMF2oj02TS3';
update content_bodies set title = 'Introducing Pension Kanon in Niseko, Hokkaido - A Must for Crab Lovers!', description = 'This channel promotes summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. In the fifth installment of the pension introduction series, we highlight ''Pension Kanon,'' perfect for crab enthusiasts. The video covers various aspects, including an overview of the pension, information about the owner who grew up in Niseko, details about the restaurant, recommended ways to enjoy crab, insights into the restaurant''s clientele, and suggestions for activities in Niseko. The filming location is Pension Kanon, and viewers are encouraged to subscribe for more videos showcasing the summer attractions of Niseko.' where id = 'OzlyZ1LaTe-nokF-YKanL';
update content_bodies set title = '【英語で朝礼】北海道ニセコからおはよー！＜2020年11月23日＞| 毎週月曜朝8時、ニセコから元気をお届け！', description = '毎週月曜日の朝8時に、北海道ニセコから元気をお届けします。週の始まりに、ニセコからの「朝礼」で元気にスタートしましょう。今日は『英語チャレンジ！』ということで、英語でのメッセージをお届けします。聞き取れますか？字幕なしで一度、次に英語字幕と日本語訳付きで繰り返します。詳細はEdVenture NisekoのウェブサイトやYouTubeチャンネルをご覧ください。' where id = '_RE6GE7buvgKbt7AvIp9x';
update content_bodies set title = 'Good Morning from Niseko, Hokkaido! <November 23, 2020> | Bringing Energy Every Monday at 8 AM!', description = 'Every Monday at 8 AM, we deliver energy from Niseko, Hokkaido! Let''s start the week with a cheerful ''morning meeting'' from Niseko. Today features an ''English Challenge!'' Can you understand the message delivered in English? We repeat it twice: first without subtitles, then with English subtitles and Japanese translations. For more information, visit EdVenture Niseko''s website and YouTube channel.' where id = '2bFBwStL6KAsfQ1vsbqMa';
update content_bodies set title = '【グルメ】北海道ニセコ絶品グルメVlog「Green Farm Cafe」 | 異日常で日常を過ごす滞在型旅行のススメ', description = 'このチャンネルは、北海道ニセコでのサマーステイを推奨するもので、倶知安観光協会が運営しています。絶品グルメVlogシリーズの第4弾では、朝から営業している「グリーンファームカフェ」を紹介し、ワーケーションにも最適としています。ニセコは冬が有名ですが、夏の魅力も伝えるためにこのチャンネルを開設しました。今後も動画をアップしていく予定で、チャンネル登録を促しています。カフェのウェブサイトやSNS、地図へのリンクも掲載されています。' where id = '5rX7xI7pndPNYH3m2gxOL';
update content_bodies set title = 'Delicious Gourmet Vlog in Niseko, Hokkaido: Green Farm Cafe | Recommendations for a Staycation in an Unusual Everyday Life', description = 'This channel promotes summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The series features gourmet Vlogs, with the fourth installment focusing on Green Farm Cafe, which opens early and is recommended for workations. The channel aims to showcase the charm of summer in Niseko, a region known for its winter attractions. Viewers are encouraged to subscribe for more videos as the channel continues to update. Links to the cafe''s website, Facebook, Instagram, and location are provided.' where id = 'OY2yDkPx2EJou_Fsol_8l';
update content_bodies set title = '北海道ニセコ絶品グルメVlog「杏ダイニング」 | 夏は北海道ニセコがオススメ！異日常で日常を過ごす滞在型旅行｜ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコでのサマーステイを推奨するもので、倶知安観光協会が運営しています。絶品グルメVlogシリーズの第1弾として「杏ダイニング」を紹介し、北海道の豊かな自然を活かした新日本食を提供しています。また、ジンジャービア『Hakko Ginger』の販売開始や、コロナウィルスの影響で卒業式が縮小された高校3年生を杏ダイニングに招待するクラウドファンディングの取り組みも紹介されています。このチャンネルは、ニセコの夏の魅力を伝えることを目的としており、今後も動画をアップしていく予定です。' where id = 'Ov6CSquxoR2XhkxcFJW7X';
update content_bodies set title = 'Delicious Gourmet Vlog in Niseko, Hokkaido: ''An Dining'' | Summer in Niseko is Recommended! Experience a Different Daily Life with a Stay-type Trip | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This channel promotes summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The first episode of the gourmet vlog series features ''An Dining,'' which offers a new Japanese dining experience that utilizes the rich natural resources of Hokkaido. The channel also highlights the launch of ''Hakko Ginger,'' a ginger beer that warms the body instantly. Additionally, a crowdfunding initiative was conducted to invite high school seniors affected by COVID-19 to enjoy a full-course meal at An Dining, supported by 192 adults, bringing smiles to many students. The channel aims to showcase the charm of summer in Niseko, encouraging viewers to subscribe for more videos.' where id = 'ZdYHoZfhRFbPIDGknOa-F';
update content_bodies set title = '【ワーケーション】北海道ニセコでワーケーションがオススメの3つの理由｜異日常で日常を過ごす滞在型旅行｜ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコエリアの倶知安観光協会が運営し、ニセコでのサマーステイを推奨しています。動画では『ワーケーションニセコがオススメの3つの理由』を紹介しており、内容は1つ目の理由（0:34）、2つ目の理由（1:36）、3つ目の理由（2:27）です。ニセコは冬が有名ですが、夏も非常に魅力的です。このチャンネルはニセコの夏の魅力を伝えるために開設され、今後も動画をアップする予定ですので、チャンネル登録をお願いしています。' where id = 'OInunIJmyZb2oUHDuQPlk';
update content_bodies set title = '3 Reasons to Recommend Workation in Niseko, Hokkaido | Staycation in an Unusual Everyday Life | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The video introduces ''Three Reasons to Recommend Workation in Niseko.'' The content includes: 1) the first reason (0:34), 2) the second reason (1:36), and 3) the third reason (2:27). While Niseko is famous for winter, summer is also highly recommended. The channel aims to convey the charm of summer in Niseko and plans to upload more videos, encouraging viewers to subscribe. For more information, visit the Kutchan Tourism Association''s website.' where id = 'j3k_Kp71hiAZq4aGXLwcV';
update content_bodies set title = '【北海道ニセコ】ペンションご紹介③「ロッヂコロポックル」| 老舗中の老舗 | ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコでのサマーステイを推奨するもので、倶知安観光協会が運営しています。ペンション紹介シリーズの第3弾として、ニセコエリアの老舗ペンション「ロッヂコロポックル」を詳しく紹介します。動画では、宿の歴史や建て替え工事、客層、リピーターの多さ、外国人客の増加などについて語られています。また、ニセコの変化や、早川さんのおすすめポイントも紹介されており、ニセコの夏の魅力を伝えることを目的としています。' where id = 'O8v4S4xY1td759-LZQXoX';
update content_bodies set title = 'Introducing Lodge Koropokkuru in Niseko, Hokkaido | A Long-Established Inn | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. In the third installment of the pension introduction series, ''Exploring Niseko''s Inns with Hayakawa-san,'' the video details the long-loved Lodge Koropokkuru. It covers the lodge''s history, renovations, customer demographics, and the increase in foreign visitors. The video also discusses the changes in Niseko over the years and includes Hayakawa-san''s recommendations. The channel aims to showcase the charm of summer in Niseko, encouraging viewers to subscribe for more content.' where id = 'U9yGdX-VxGJKrc47zb4zR';
update content_bodies set title = '【分散型旅行】北海道ニセコで秋を探しに行くよ！（紅葉vlog）＝神仙沼＝ | ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコエリアでのサマーステイを推奨するもので、倶知安観光協会が運営しています。動画では、ニセコエリアの秋の風景を楽しむためののんびりドライブを紹介しており、特に神仙沼の紅葉が見どころです。撮影日は2020年10月14日で、ドライブ中と神仙沼での紅葉を楽しむ様子が収められています。パノラマラインのゲートは10月26日に冬期封鎖されるため、それまでに訪れることを勧めています。ニセコは冬が有名ですが、夏の魅力も伝えるためにこのチャンネルが開設され、今後も動画がアップされる予定です。' where id = 'SDbUbeP1gc-eMcKlLYqgW';
update content_bodies set title = 'Exploring Autumn in Niseko, Hokkaido! (Autumn Leaves Vlog) = Shinsen-numa = | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The video showcases a leisurely drive to enjoy the autumn scenery in the Niseko area, specifically highlighting Shinsen-numa. Filmed on October 14, 2020, it features beautiful autumn leaves during the drive and at Shinsen-numa. Note that the gate on the Panorama Line will close for winter on October 26, so visitors are encouraged to go before then, ideally with winter tires. The channel aims to promote the summer attractions of Niseko, which is famous for its winter activities. More videos will be uploaded, and viewers are encouraged to subscribe.' where id = 'xfaS8-lJu8VzO5S3cFqiM';
update content_bodies set title = '【北海道ニセコ】ペンションご紹介②「旅の交差点」| 昔ながら愛されるペンション | ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコでのサマーステイをオススメするもので、倶知安観光協会が運営しています。ペンション紹介シリーズ第2弾では、『早川さんと行く！ニセコのペンション詳しく知り隊』として、ニセコエリアの愛されるペンションを詳しく紹介します。動画では、ペンションを始めたきっかけや冬のお客様の特徴、長期滞在の過ごし方、リピーターとのエピソード、おすすめの過ごし方、ニセコの魅力などが語られます。撮影場所は「旅の交差点」で、ニセコの夏の魅力を伝えるためにチャンネルが開設されました。今後も動画をアップ予定ですので、チャンネル登録を歓迎しています。' where id = 'r624obQOtOsJ499rsnWVH';
update content_bodies set title = 'Introducing Pension in Niseko, Hokkaido: ''Tabi no Kousaten'' | A Beloved Traditional Pension | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. In the second installment of the pension introduction series, titled ''Let''s Learn About Niseko''s Pension with Hayakawa-san!'', the video details a beloved pension in the Niseko area. It covers various topics including the reasons for starting the pension, the type of winter guests, how to enjoy long winter stays, stories with repeat visitors, recommended activities, and the appealing aspects of living in Niseko. The filming location is ''Tabi no Kousaten''. The channel aims to showcase the charm of summer in Niseko, encouraging viewers to subscribe for more videos.' where id = 'BHeNyvAeYeqxS0K98p5eb';
update content_bodies set title = '【グルメ】北海道ニセコ絶品グルメVlog「比羅夫坂」 | 異日常で日常を過ごす滞在型旅行のススメ', description = 'このチャンネルは、北海道ニセコエリアの倶知安観光協会が運営し、夏の滞在を推奨しています。絶品グルメVlogシリーズの第3弾では、ラグジュアリーホテル「比羅夫坂」を紹介し、ゆったりとした時間を楽しむ様子を伝えています。ニセコは冬が有名ですが、夏の魅力も多く、これを伝えるためにチャンネルを開設しました。挨拶編として始まりますが、今後も動画をアップしていく予定ですので、チャンネル登録をお願いしています。ホテルのウェブサイトやSNS、地図へのリンクも提供されています。' where id = 'Taox47bpf8JU1AJpblheX';
update content_bodies set title = 'Gourmet Vlog of Niseko, Hokkaido: Hirafuzaka | Recommendations for Staying in a Different Everyday Life', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The third volume of the gourmet vlog series features Hirafuzaka, where guests can enjoy a leisurely time in a luxury hotel. The channel aims to showcase the charm of summer in Niseko, which is famous for its winter attractions. Although this introductory video is just the beginning, more content will be uploaded soon, and viewers are encouraged to subscribe. The channel also provides links to the hotel website, social media, and a map for easy access.' where id = '7FExtAa9IK4vwnBz9FzTd';
update content_bodies set title = 'ニセコ旅行するなら、コレがオススメ！目的別にご紹介！｜異日常で日常を過ごす滞在型旅行｜ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコでのサマーステイをオススメしています。倶知安観光協会が運営し、北海道旅行やニセコ旅行に役立つ旅行雑誌を紹介します。特に、ニセコを楽しむために必須の雑誌として、るるぶ北海道''21、まっぷる北海道''21、じゃらんで旅する北海道2020-21年版、北海道情報誌「HO」を取り上げています。撮影場所は樺山ハウス（ホリデーニセコ）で、ニセコは冬だけでなく夏も魅力的です。このチャンネルでは、ニセコの夏の魅力を伝えるために動画をアップしていく予定で、視聴者にはチャンネル登録を促しています。' where id = 'VK0MHiJMDZSptPlGA0oG5';
update content_bodies set title = 'Recommended for Your Trip to Niseko, Hokkaido! A Guide Based on Purpose! | Stay-type Travel in an Extraordinary Daily Life | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The video introduces recommended travel magazines for those planning a trip to Hokkaido and Niseko, highlighting essential magazines to enjoy the area. Featured magazines include ''Rurubu Hokkaido 2021'', ''Mapple Hokkaido 2021'', ''Jalan Travel Hokkaido 2020-21'', and ''HO Hokkaido Information Magazine''. The filming location is Kabayama House (Holiday Niseko). While Niseko is famous for winter, summer is also highly recommended, and the channel aims to convey the charm of summer in Niseko. Viewers are encouraged to subscribe for more videos.' where id = 'DxuCE7duDcBRHu8jzK-BQ';
update content_bodies set title = '【グルメ】北海道ニセコ絶品グルメVlog「Harvest cafe」 | 夏は北海道ニセコがオススメ！異日常で日常を過ごす滞在型旅行｜ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコでのサマーステイを推奨するもので、倶知安観光協会が運営しています。絶品グルメVlogシリーズの第2弾として、オーガニックで野菜たっぷりの食事が楽しめる「Harvest cafe」を紹介しています。ニセコは冬が有名ですが、夏も魅力的な観光地です。このチャンネルでは、ニセコの夏の魅力を伝えるために動画を定期的にアップしていく予定で、視聴者にはチャンネル登録を促しています。' where id = 'kjT2CIAl8n2C7hofTVo5h';
update content_bodies set title = 'Delicious Gourmet Vlog in Niseko, Hokkaido: Harvest Cafe | Summer in Niseko is Recommended! Experience a Different Daily Life with a Stay Trip | Niseko Summer Stay (Kutchan Tourism Association)', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The second volume of the gourmet vlog series features Harvest Cafe, known for its organic and vegetable-rich meals. While Niseko is famous for winter sports, the summer season also offers unique attractions. The channel aims to showcase the charm of summer in Niseko, with plans to upload more videos regularly. Viewers are encouraged to subscribe for updates.' where id = '2GWl5rn50isr-X14I1lUg';
update content_bodies set title = '【Go To トラベル】ニセコ旅行計画編「今、ニセコ旅行を計画するなら！」', description = 'このチャンネルは、北海道ニセコエリアの倶知安観光協会が運営し、ニセコでのサマーステイを推奨しています。今回の動画では、コロナ禍におけるニセコ旅行計画の重要なポイントを説明しています。Go Toトラベルや参加宿泊施設リスト、新しい旅のエチケットなどのリンクも提供されています。ニセコは冬が有名ですが、夏の魅力も伝えたいと考えています。今後も動画をアップしていく予定なので、チャンネル登録をお願いしています。' where id = 'oSVKXcQuq6yomBcQn3cEP';
update content_bodies set title = 'Planning Your Trip to Niseko: A Guide to Summer Stays', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The video focuses on important points to consider when planning a trip to Niseko during the COVID-19 pandemic. It provides links to various resources, including the Go To Travel campaign, a list of participating accommodations, and new travel etiquette. The channel aims to showcase the charm of summer in Niseko, which is often known for its winter activities. Viewers are encouraged to subscribe for more videos highlighting the summer attractions of the area.' where id = 'up-UWIflfoSxtIpVjJ0LA';
update content_bodies set title = '【農業女子と学ぶ】この野菜、なぁに？ー初級編ー | 夏は北海道ニセコがオススメ！異日常で日常を過ごす滞在型旅行｜ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコでのサマーステイを推奨するもので、倶知安観光協会が運営しています。今回の動画は、農業女子と一緒に行う初級編の野菜クイズで、野菜の葉っぱを見て何の野菜かを当てる内容です。4問のクイズに挑戦し、正解を目指します。協力しているのは、オーガニック野菜を栽培する『ニセコグリーンファーム』で、農業体験や石窯ビザづくり体験が楽しめます。ニセコは冬が有名ですが、夏の魅力も多く、このチャンネルではその魅力を発信していく予定です。動画を楽しんでいただけたら、チャンネル登録をお願いします。' where id = 'ndNf1tL08ZkxUnhRktw0P';
update content_bodies set title = 'Learn About Vegetables with Agricultural Women: Beginner''s Edition | Recommended Summer Stay in Niseko, Hokkaido!', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. The featured video is a beginner-level vegetable quiz where viewers guess the type of vegetable based on its leaves. Participants are encouraged to answer four questions. The video collaborates with Niseko Green Farm, known for its organic vegetable cultivation and recommended experiences like agricultural activities and stone oven pizza making. While Niseko is famous for winter sports, the summer attractions are equally appealing, and the channel aims to showcase the summer charm of Niseko. Viewers are encouraged to subscribe for more upcoming videos.' where id = '3JChXjf5HFoy5hz3vUz53';
update content_bodies set title = '【北海道】夏はニセコがオススメ！「ニセコをざっくり理解しよう！」異日常で日常を過ごす滞在型旅行', description = 'このチャンネルは、北海道ニセコでのサマーステイを推奨するもので、倶知安観光協会が運営しています。現在の状況では観光が難しいですが、コロナウィルスが終息した際には、ニセコが旅行先の一つとして選ばれることを願っています。動画ではニセコの概要を紹介し、ガイドブックを参照する際のイメージを持ちやすくしています。また、初めて「ザ・グリーンリーフ・ニセコビレッジ」というホテルを紹介しました。ニセコは冬が有名ですが、夏も魅力的であることを伝えるためにこのチャンネルを開設しました。今後も動画をアップしていく予定ですので、チャンネル登録をお願いできれば嬉しいです。' where id = 'lRZTlKmmPAteq89HeKVME';
update content_bodies set title = 'Niseko in Summer: A Recommended Stay! Understanding Niseko in Brief for a Unique Travel Experience', description = 'This channel promotes summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. Given the current situation, travel may not be feasible, but we hope that when the COVID-19 pandemic subsides, Niseko will be a travel option for many. In this video, we provide a brief introduction to Niseko, which will help viewers visualize the area when consulting guidebooks. We also introduce the Green Leaf Niseko Village hotel for the first time. While Niseko is famous for winter, summer is equally appealing, and this channel aims to showcase the summer attractions of Niseko. We plan to upload more videos, and we would appreciate your subscription.' where id = 'TEQKjC60HlsxA1VfoW_RE';
update content_bodies set title = '【北海道】夏はニセコがオススメ！「ニセコを一言でいうと？」', description = 'このチャンネルは、北海道ニセコでのサマーステイを推奨するもので、倶知安観光協会が運営しています。現在の状況では観光が難しいですが、コロナウィルスが終息した際には「北海道ニセコ」が旅行先の選択肢に入ることを願っています。今回の動画では「ニセコを一言で表現」し、その理由を2つお話しします。結論まで見ていただけると嬉しいです。また、初めてのホテル「ザ・グリーンリーフ・ニセコビレッジ」も紹介しています。ニセコは冬が有名ですが、夏の魅力も伝えたくてこのチャンネルを開設しました。今後も動画をアップしていく予定ですので、チャンネル登録をお待ちしています。' where id = '3hOqSAOAXdwXpxxhGB7TE';
update content_bodies set title = 'Niseko in Summer: A Recommended Stay Experience', description = 'This channel promotes summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. Although current circumstances limit travel, we hope that once the COVID-19 pandemic is over, Niseko will be a top choice for travelers. In this video, we express what Niseko means in one word and provide two reasons to support this description. We encourage viewers to watch until the conclusion. The video features the introduction of a new hotel, The Green Leaf Niseko Village. While Niseko is famous for winter sports, we aim to showcase the summer attractions of the area. We plan to upload more videos, and we would appreciate your subscription to our channel.' where id = 'Reun4TXRSGV9yec8zE_m3';
update content_bodies set title = '【仕事紹介】観光協会のおしごとって？イベント企画編 観光業に興味ある大学生にオススメ!/ 北海道ニセコ「NISEKOくっちゃんエール飯」｜ニセコサマーステイ（倶知安観光協会）', description = 'このチャンネルは、北海道ニセコエリアにある倶知安観光協会が運営し、サマーステイをオススメしています。現在の状況では観光が難しいですが、コロナウイルスが終息した際には「北海道ニセコ」が旅行先の一つとして選ばれることを願っています。今回の動画では観光協会の仕事、特にイベント企画について紹介し、現在実施中の「NISEKOくっちゃんエール飯」を例に挙げています。撮影場所はニセコエリアの高級コンドミニアム「綾ニセコ」で、ニセコの夏の魅力を伝えるためにチャンネルを開設しました。今後も動画をアップしていく予定なので、ぜひチャンネル登録をお願いします。' where id = 'iV-ypSg9g6xlHcGVKPOYP';
update content_bodies set title = 'Job Introduction: What Does a Tourism Association Do? Event Planning Edition - Recommended for University Students Interested in the Tourism Industry! / NISEKO Kucchan Yell Meal - Niseko Summer Stay (Kutchan Tourism Association)', description = 'This channel recommends summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. Although current circumstances limit travel, we hope that once the COVID-19 pandemic is over, ''Niseko, Hokkaido'' will be a travel option. This video introduces the work of tourism associations, specifically how they plan events, using the ongoing ''NISEKO Kucchan Yell Meal'' as an example. For more information about this meal, check out our previous YouTube video. The filming location is a luxurious condominium in the Niseko area, ''Aya Niseko.'' The channel aims to showcase the summer attractions of Niseko, which is famous for winter tourism. We plan to upload more videos, so please subscribe!' where id = 'dW76BsNjLAluPF25sxW5y';
update content_bodies set title = '【北海道ニセコ】おうち時間をニセコと共に②～自然に癒されるweb写真展Nature～', description = 'このチャンネルは、北海道ニセコエリアの倶知安観光協会が運営し、サマーステイを推奨しています。現在の状況では観光が難しいですが、コロナウイルスが終息した際にニセコが旅行先の一つとして選ばれることを願っています。今回の動画では、ニセコを含む後志エリアの自然を楽しめるweb写真展「Nature」を紹介します。主催の横山孝博さんがゲストとして登場し、写真を通じて癒しを提供します。展示は2020年4月25日から5月31日まで行われ、毎週新しい作品が公開されます。ニセコは冬が有名ですが、夏の魅力も伝えていく予定です。' where id = 'l0PS4dPNLZs_yQWzkzIAU';
update content_bodies set title = 'Niseko, Hokkaido: Enjoying Home Time with Nature - A Web Photo Exhibition', description = 'This channel promotes summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. Given the current situation, traveling may not be feasible, but we hope that once the COVID-19 pandemic is over, Niseko will be a travel option for many. The video introduces a web photo exhibition titled ''Nature,'' showcasing the beautiful scenery of the Shiribeshi area, including Niseko, which can be enjoyed from home. The exhibition is organized by Takahiro Yokoyama of the SHIRIBESHI ART NETWORK. The purpose of the exhibition is to provide a glimpse of stunning photographs that offer maximum healing. The exhibition runs from April 25 to May 31, 2020, with new works uploaded every week. While Niseko is famous for winter, summer is also highly recommended, and this channel aims to share the charm of summer in Niseko.' where id = '4AX30jY92KZbKKaC7qg8z';
update content_bodies set title = '【北海道ニセコ】おうち時間をニセコと共に①～子供と一緒に楽しめるダルマプロジェクト～', description = 'このチャンネルは、北海道ニセコエリアの倶知安観光協会が運営し、サマーステイを推奨しています。現在の状況では観光が難しいですが、コロナウイルスが終息した際にはニセコが旅行先の一つとして選ばれることを願っています。今回の動画では、子供と一緒に楽しめるダルマプロジェクトを紹介し、主催者のキヨエギャラリーニセコの細川清映さんがゲストとして登場します。ダルマの意味や外国人の反応についても触れ、実際に体験した様子をお伝えします。ニセコの夏の魅力を発信するためにチャンネルを開設し、今後も動画をアップしていく予定ですので、ぜひチャンネル登録をお願いします。' where id = '8o0GAwqW1yFb33pUnHpRe';
update content_bodies set title = 'Niseko, Hokkaido: Enjoying Home Time with the Daruma Project - A Staycation Experience', description = 'This channel promotes summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. Given the current situation, traveling may not be feasible, but we hope that once the COVID-19 pandemic is over, Niseko will be a travel option. In this video, we introduce the Daruma Project, which can be enjoyed at home with children. Kiyoegallery Niseko''s Kiyoe Hosokawa is a guest, discussing the meaning of Daruma, foreign reactions to it, and sharing her own experience with the project. The channel aims to showcase the summer attractions of Niseko, which is famous for its winter activities. We plan to upload more videos, so subscribing would be appreciated.' where id = 'N81C61tZfvtvji0dGA0x4';
update content_bodies set title = '【宮城観光/グルメ】知らなきゃ損！宮城で食べたい絶品ランチグルメ8選', description = 'この動画は宮城県を訪れる旅行者に向けて、絶対に食べてほしいランチグルメスポット8選を紹介しています。動画で紹介されていないおすすめがあれば、ぜひコメント欄でシェアしてください。チャンネル「旅行の達人」は、観光、移動、宿泊、食事など、旅行に関するさまざまな情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。最新情報や更新については、公式のSNSアカウントをフォローしてください。' where id = 'QMAdasKelXWi2LskBufuT';
update content_bodies set title = 'Must-Try Lunch Gourmet in Miyagi: 8 Recommendations', description = 'This video serves as a guide for those traveling to Miyagi Prefecture, showcasing eight must-try lunch spots. If you have any additional recommendations not mentioned in the video, feel free to share them in the comments. The channel, ''Travel Master,'' aims to enhance your travel experience by providing a wealth of information on various travel-related topics, including sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities and experiences. For more information and updates, follow their official social media accounts.' where id = 'aJHGZL5yKyPC-zXc9Dyq2';
update content_bodies set title = '直島　極上のクリエイティブ', description = '直島は、あちらこちらにアートが点在し、昼も夜もアートな空間に包まれる島です。路地に一歩足を踏み入れると、古くから瀬戸内海の海運と共に栄えてきた文化が今なお残っており、現代アートと融合したクリエイティブな様子を垣間見ることができます。' where id = 'ig2V9LcOXb3HUrxlLuVS1';
update content_bodies set title = 'Naoshima: A Creative Paradise', description = 'Naoshima is an island where art is scattered everywhere, enveloping visitors in an artistic atmosphere both day and night. By stepping into the alleys, one can glimpse the culture that has thrived alongside the Seto Inland Sea''s maritime trade since ancient times, intertwined with contemporary art to create a unique creative experience.' where id = 'U3REI28EvvKzDg6Ivmi8x';
update content_bodies set title = '【三重県】まるで“ピンクの絨毯”', description = '三重県の志摩市観光農園では、なだらかな斜面に広がるコスモスやネモフィラが咲き誇り、まるで“ピンクの絨毯”のような美しい景色を楽しむことができます。開園は花の開花に合わせて行われ、今年は11月19日までコスモス畑が楽しめます。かわいい写真が撮れるフォトスポットもあり、特にコキアのまんまるな姿も見どころです。11月には真っ赤に色づくコキアも見られるかもしれません。開園期間中でも開花状況によっては期間が短くなることがあるため、訪れる前にInstagramで確認することをお勧めします。入園料は300円で、駐車場は無料です。' where id = '0Lzervzz_T7v-mFd0GmZs';
update content_bodies set title = 'Mie Prefecture: A ''Pink Carpet'' Experience', description = 'In Mie Prefecture, visitors can enjoy a stunning view of blooming flowers resembling a ''pink carpet'' on gentle slopes. The park opens in line with the blooming of cosmos and nemophila, offering a colorful display throughout the seasons. This year, the cosmos field will be available until November 19, providing a perfect photo spot for capturing memories. Additionally, visitors can see the adorable round shape of ''kochia,'' which may turn bright red in November. Please note that the opening period may change based on blooming conditions, so check Instagram for updates before visiting. The park is located in Shima City, Mie Prefecture, with an entrance fee of 300 yen and free parking available.' where id = 'hbtbCmwQCnesJt2eL-1Sk';
update content_bodies set title = '自然を五感で味わえるレストラン【三重県】', description = '三重県いなべ市にあるこのレストランは、緑豊かな庭に囲まれた空間で、自然を五感で楽しむことができます。2022年のオープン以来、メディアで注目を集めており、旬の地域食材を使った料理を提供しています。特に人気の看板メニューはロールキャベツです。大きな窓のある開放的な店内では、どの席からでも美しい庭を眺めることができます。営業時間は11:00から17:00までで、金・土・日曜は21:00まで営業。水曜日と第1・第3木曜日が定休日で、無料駐車場も完備されています。' where id = '0szQ0S3TL8d0Bb3lXJPtq';
update content_bodies set title = 'A Restaurant in Mie Prefecture to Experience Nature with All Five Senses', description = 'This restaurant, surrounded by a lush garden, offers a unique dining experience where guests can enjoy nature through all five senses. Since its opening in 2022, it has gained significant media attention for its use of seasonal local ingredients. The signature dish, rolled cabbage, is particularly popular. The spacious interior features large windows, allowing diners to enjoy beautiful garden views from any seat. Located in Inabe City, Mie Prefecture, the restaurant operates from 11:00 AM to 5:00 PM, with extended hours on weekends. Closed on Wednesdays and the first and third Thursdays of the month, it also offers free parking and is accessible via the Tokai Kanjo Expressway.' where id = 'uZePUzBZtTeIJAqOwSrYH';
update content_bodies set title = '⛩2023年最新！おはらい町グルメ5選✨', description = '伊勢神宮を参拝した後は、お土産やグルメを楽しみたいものです。「おはらい町」には魅力的なグルメがたくさんあります。今回は特におすすめのスポットを5つ紹介します。1) 「はちみつ屋 松治郎の舗」では、ハニーポテトが人気。2) 「山村みるくがっこう」では、ぷりんソフトが絶品。3) 「伊勢プリンの鉄人」では、ユニークなプリンとトーストが楽しめます。4) 「まるごと果汁店」では、新鮮な果汁が味わえます。5) 「イモンネ」では、ジェラ餅が人気です。詳しい情報は過去の投稿や「観光三重」でも紹介されていますので、ぜひチェックしてみてください。' where id = 'Vo1_t7wHxq7dyICN4tmDG';
update content_bodies set title = 'Latest 2023! Top 5 Gourmet Spots in Oharaimachi✨', description = 'After visiting Ise Jingu, you want to enjoy unique experiences and delicious souvenirs. Oharaimachi is filled with enticing gourmet options. Here are some recommended spots: 1) Matsujirou Honey Shop - famous for honey and honey potatoes. 2) Yamamura Milk School - known for its delicious pudding soft serve. 3) Ise Pudding Master - offers unique pudding and toast. 4) Marugoto Juice Shop - specializes in fresh juices. 5) Imonne - famous for its gelato mochi. For more details, check out past posts and the Kankomie website!' where id = 'WSRPnu21_O3TeT4SW4gk0';
update content_bodies set title = 'おかやまフルーツカレンダー', description = '「くだもの王国おかやま」から、鮮やかで新鮮なフルーツの動画をお届けします。「晴れの国おかやま」が誇るフルーツをぜひご堪能ください。' where id = 'tMjoDk-dGRcag2lj7fUYR';
update content_bodies set title = 'OKAYAMA FRUIT CALENDAR', description = 'The ''Fruit Kingdom Okayama'' presents a variety of fresh and visually stunning fruit videos. Enjoy the fruits that Okayama, known as the ''Sunny Country,'' takes pride in.' where id = '0m2MFnQLWF6KMduinZvFN';
update content_bodies set title = '千年の歴史を持つ神社「備前国総社宮」　～お祭り・神輿担ぎ体験～', description = '備前国総社宮は平安時代に創建され、岡山の128の神社のご祭神を合祀した神社です。この神社にお参りすることで、すべての神社に一度にお参りしたことになると言われています。1992年に放火で焼失した拝殿は、平安時代の社殿を復元して再建され、全国でも唯一の美しい拝殿です。また、龍ノ口の山の麓に位置し、日本有数のパワースポットとしても知られています。ここでは、伝統的なお祭りや神輿担ぎの体験、獅子舞奉納、岡山の食を楽しめる屋台出店など、特別な体験が提供されています。' where id = 'sHDsVsW--lqxmHG0nN39x';
update content_bodies set title = 'Bizen Kuni Sōja Shrine: A Thousand-Year History - Festival and Mikoshi Experience', description = 'Founded in the Heian period, Bizen Kuni Sōja Shrine enshrines the deities of 128 shrines in Okayama. Visiting this shrine is said to be equivalent to paying respects to all the associated shrines at once. The shrine features a beautiful hall of worship, reconstructed in 1992 after a fire, reflecting the architectural style of the Heian period, making it unique in Japan. Located at the foot of Mount Ryunokuchi, it is also recognized as a significant power spot. Visitors can engage in traditional cultural experiences such as carrying the mikoshi (portable shrine), lion dance performances, and enjoy local Okayama cuisine at food stalls, providing a special and immersive experience of Japan''s rich traditions.' where id = 'vuLZTCzAHFsgetyusMVwj';
update content_bodies set title = '日本で唯一「あたまの宮」と名づく神社', description = '受験シーズンが到来し、三重県大紀町にある「頭之宮四方神社」は、日本で唯一「あたまの宮」と名づけられた神社です。この神社は頭の守り神様の御神徳が得られるとされ、学力向上や合格祈願を求める学生が県内外から訪れます。また、三重県には受験生を応援するための他の神社も多く、合格や学業成就を祈るためのスポットがたくさんあります。詳細はリンク先で確認できます。' where id = 'adTulcJ_3B2wPLKr5AfJD';
update content_bodies set title = 'The Only Shrine Named ''Atamanomiya'' in Japan', description = 'The entrance examination season has begun, and Koubenomiya Shikata Shrine in Taiki Town is the only shrine in Japan named ''Atamanomiya'' (shrine of the head). This shrine is believed to provide divine virtues from the guardian god of the head, attracting students from across the prefecture and beyond who seek better academic performance and success in their exams. Additionally, Mie Prefecture is home to many other shrines that support students preparing for entrance exams, offering various places to pray for success and academic achievement. More information can be found at the provided link.' where id = 'UFzNv3Q_anUahTcxjjgOy';
update content_bodies set title = '「的矢かき」養殖場直営のレストラン🦪', description = '三重ブランド第一号の「的矢かき」は、その美味しさと生で食べても安心安全な品質の高さで国内外から注目を集めています。2022年、佐藤養殖場のすぐ隣にオープンした「的矢かきテラス」では、自社養殖の新鮮な牡蠣が一年中楽しめると話題です。冬に人気の「鉄鍋蒸し焼き牡蠣」や、牡蠣を使った8品が楽しめる「牡蠣づくし定食」などが提供されています。場所は志摩市で、駐車場は18台分の無料スペースがあります。営業時間は10:00～15:00で、火曜日は定休日です。' where id = '47k_lrKMDewjQWsaxJr_P';
update content_bodies set title = 'Directly Operated Restaurant of ''Matoya Oysters'' 🦪', description = 'The ''Matoya Oysters'', recognized as the first brand of Mie Prefecture, is gaining attention both domestically and internationally for its delicious taste and high quality, which is safe to eat raw. In 2022, the ''Matoya Oyster Terrace'' opened right next to Sato Aquaculture, allowing visitors to enjoy fresh oysters year-round. The restaurant is particularly popular in winter for its ''Iron Pot Steamed Oysters'' and offers a ''Oyster Full Course'' featuring eight dishes made with oysters. The restaurant is located in Shima City, with free parking available for 18 cars. It operates from 10:00 AM to 3:00 PM, closed on Tuesdays.' where id = 'Wjt618Jz6cfibTbRHidYG';
update content_bodies set title = '【北海道】夏はニセコがオススメ！チャンネルスタート編', description = 'このチャンネルは、北海道ニセコでのサマーステイをオススメする初撮影動画です。運営は倶知安観光協会で、現在の情勢では観光が難しいですが、コロナウィルスが終息した際に「北海道ニセコ」が旅行先の選択肢に上がることを願っています。ニセコは冬が有名ですが、夏も魅力的です。このチャンネルでは「ニセコの夏の魅力」を伝えるために開設されました。今回はご挨拶編ですが、今後も動画をアップしていく予定ですので、チャンネル登録をお願いできれば嬉しいです。撮影場所はバケーションニセコの「ハナ＆ジョー」です。' where id = '5dkCZYRoMI7DUOCKuYRM_';
update content_bodies set title = 'Niseko in Summer: Recommended Stay! Channel Launch Edition', description = 'This is the first video of a channel recommending summer stays in Niseko, Hokkaido, operated by the Kutchan Tourism Association. Given the current situation, travel may not be feasible, but we hope that once the COVID-19 pandemic is over, Niseko will be a top choice for travelers. While Niseko is famous for winter sports, summer in the area is also highly recommended. This channel was created to showcase the summer attractions of Niseko. Although this video serves as an introduction, we plan to upload more content regularly, and we would appreciate your subscription. The filming location for this video is ''Hana & Joe'' by Vacation Niseko.' where id = '8xKSrEeoOLfzJ4L-2ztns';
update content_bodies set title = '愛媛グルメの新発見！味も満足、コスパ最強の絶品スポット7選', description = 'この動画は愛媛県を訪れる旅行者や観光客のためのガイドです。美味しい料理と優れたコストパフォーマンスを提供する7つの絶品グルメスポットを紹介しています。視聴者は、動画で紹介されていないおすすめの場所があればコメント欄でシェアするよう促されています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行を通じて人生を豊かにすることを目指しています。動画では、各スポットの詳細情報が含まれており、視聴者が訪問計画を立てやすくなっています。' where id = 'Gdw682CDcink99EhonfD6';
update content_bodies set title = 'Discover New Gourmet Spots in Ehime: 7 Must-Visit Places with Great Taste and Value', description = 'This video serves as a guide for travelers and tourists visiting Ehime Prefecture. It highlights seven exceptional gourmet spots that offer both delicious food and excellent cost performance. Viewers are encouraged to share their own recommendations in the comments if they know of any other great places not mentioned in the video. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a wealth of information on sightseeing, transportation, accommodation, and dining, with a mission to enrich lives through travel. The video includes detailed information about each featured location, ensuring viewers can plan their visits effectively.' where id = 'HL1rlpPRPhkTG3P_4Z7Hm';
update content_bodies set title = '地元で愛される絶品スポットを巡ろう府中市の人気観光＆グルメ7選', description = 'この動画は東京都への旅行を計画している方に向けて、府中市のおすすめスポットを紹介しています。視聴者には、動画で紹介されていないおすすめの場所をコメントでシェアするよう呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見できるようにサポートしています。動画では、府中市郷土の森博物館やJRA競馬博物館など、7つの注目スポットが紹介されています。' where id = 'gZrOqDFtFvIS2WEa5vmg7';
update content_bodies set title = 'Explore Fuchu City: 7 Popular Tourist and Gourmet Spots Loved by Locals', description = 'This video serves as a guide for those traveling to Tokyo, specifically highlighting recommended spots in Fuchu City. It encourages viewers to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a variety of information related to sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and aims to inspire viewers to discover new possibilities and enjoy their journeys. The video features seven notable locations, including the Fuchu City Local History Museum and the JRA Horse Racing Museum, among others.' where id = 'MJA9Ke0Gm3FUCah1G-v6j';
update content_bodies set title = '苫小牧市で見つけた！観光もグルメも楽しめる穴場スポット8選', description = 'この動画では、北海道苫小牧市の観光とグルメを楽しめる8つの穴場スポットを紹介しています。北海道への旅行を計画している方にとって、参考になる内容です。視聴者には、コメント欄で自分のおすすめスポットをシェアすることが奨励されています。また、チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目指しています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者に新しい可能性を発見する旅を促しています。' where id = '1gIvnn9FwBEfnNn72VTxz';
update content_bodies set title = 'Hidden Gems in Tomakomai City: 8 Spots for Sightseeing and Gourmet Experiences', description = 'This video introduces eight hidden spots in Tomakomai City, Hokkaido, perfect for sightseeing and enjoying local cuisine. It serves as a guide for travelers planning a trip to Hokkaido. Viewers are encouraged to share their own recommendations in the comments section. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a variety of information related to sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = '8LJxU45tcHqeoXu3e1sgg';
update content_bodies set title = '日向市で味わう王道の魅力。歴史と絶景そしてグルメが彩る旅８選', description = 'この動画は、宮崎県日向市を訪れる際の参考として、歴史的な名所や絶景、グルメを楽しめる8つの観光スポットを紹介しています。視聴者には、他のおすすめスポットをコメントでシェアするよう呼びかけています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行をより楽しくすることを目的としています。メンバーは旅行を通じて人生を豊かにすることを信じており、視聴者が新しい可能性を発見する手助けをしたいと考えています。' where id = 'lFS-BrJ_s5J22zoil4bcd';
