update content_bodies set title = 'Okinawa''s Largest Illumination: Southeast Botanical Garden Okinawa Tropical Illumination 2021-2022', description = 'This year, the Southeast Botanical Garden presents its illumination in stunning 4K video. Enjoy a stroll through the garden from the comfort of your home. The host, TOMA, is vaccinated against COVID-19. Visiting the site can be challenging for both local and out-of-prefecture visitors, so this video allows you to experience the ambiance of a walk in Okinawa. For more videos from ''Okinawa Sanpo,'' visit the provided YouTube channel link.' where id = 'EIiyQ2maLxM2cROjUisQD';
