update content_bodies set title = 'Introducing Okinawan Snacks and Side Dishes from the Most Vibrant ''JA Farmers Market Champuru Market'' in Okinawa City', description = 'This video features TOMA visiting the JA Okinawa Farmers Market Champuru in Togawa, Okinawa City, where he introduces various Okinawan snacks and side dishes while shopping for vegetables. TOMA has received the COVID-19 vaccine. Although visiting the location may be challenging for both local and out-of-prefecture visitors, this video allows viewers to enjoy a stroll through Okinawa virtually.' where id = 'Ig2qsMrjPljw_jbbDGvb2';
