update content_bodies set title = 'Exploring the Healing Mangrove Forest of Okushigawa in Kin Town, Okinawa', description = 'This video features a stroll through the mangrove forest along the Okushigawa River in Kin Town, showcasing a unique landscape found nowhere else on the main island of Okinawa. It is an area that everyone should visit at least once. The host, TOMA, has received the COVID-19 vaccine. Due to the challenges of visiting the location in person, this video allows viewers to enjoy the walking experience virtually. For more videos from ''Okinawa Sanpo,'' you can visit their YouTube channel.' where id = 'LvcOZToiO1L-pcUxKrF95';
