update content_bodies set title = 'Charming Stroll on Yachimun Street Near Kokusai Street ♯172 Naha City Okinawa Walk Okinawa Tourism', description = 'This video takes you on a peaceful stroll down Yachimun Street in Tsuboya, where you can feel the history and culture of Okinawa. After walking through the lively Kokusai Street, be sure to explore this quiet street. The host, TOMA, is vaccinated against COVID-19. For more videos from ''Okinawa Walk'', visit the provided YouTube channel link. Visiting the area can be challenging, whether you''re from within or outside the prefecture, so enjoy the walking experience through this video.' where id = 'T_e_Qp4DQNLCJIQj2Xja9';
update content_bodies set title = '那覇のど真ん中「国際通りの裏通りは昭和の街並み 後編」', description = '前編の「国際通り」南側の裏通りに続き、今回は北側を散歩します。那覇の中心に残る「昭和の街並み」を紹介し、昭和の古いオキナワン家屋がこれほど多く残っていることに驚きました。配信者のTOMAはコロナワクチン接種済みです。現地を訪れるのが難しい方も多いと思いますので、この動画で一緒に散歩気分を楽しんでください。' where id = 'lQO7sbIId94meRCwiT9N_';
