update content_bodies set title = '旧外人住宅街のお洒落な「港川ステイツサイドタウン」をさんぽ。', description = '今回の動画では、沖縄県浦添市にある旧外人住宅をリノベーションした「港川ステイツサイドタウン」を散策します。お洒落な店舗が並ぶこのエリアは観光の定番スポットです。配信者のTOMAはコロナワクチン接種済みです。現地を訪れるのが難しい今、動画を通じて散歩気分を楽しんでいただければと思います。「@おきなわ👣さんぽⓇ」の全動画はYouTubeチャンネルでご覧いただけます。' where id = 'Yw1hfoGOHLtIKaucZpenN';
update content_bodies set title = 'Strolling through the Stylish ''Mikawa Stateside Town'' in the Old Foreigners'' Residential Area', description = 'This video features a walk through ''Mikawa Stateside Town'' in Urasoe City, Okinawa, a trendy area filled with renovated buildings from the old foreign residential district. The host, TOMA, is vaccinated against COVID-19. Given the challenges of visiting in person, this video offers a chance to enjoy the atmosphere of the area virtually. For more videos from ''@okinawa👣sampoⓇ'', visit their YouTube channel.' where id = 'LWjfTTCKViVcDzxJnuLKA';
update content_bodies set title = '本格的老舗レストラン「PIZZA HOUSE」でランチ。ホテル外のレストランとしてはトップランク in 浦添市', description = '今回は、浦添市港川にある創業60年の老舗レストラン「PIZZA HOUSE」で息子とランチを楽しみました。配信者のTOMAはコロナワクチン接種済みです。県外・県内を問わず、現地を訪れるのは難しいですが、この動画を通じて沖縄の魅力を感じながら散歩気分を楽しんでいただければと思います。' where id = 'Rqzser7ReNosZI76m3tbK';
update content_bodies set title = 'Authentic Long-established Restaurant ''PIZZA HOUSE'' for Lunch - Top Rank in Urasoe City', description = 'This time, I had lunch with my son at ''PIZZA HOUSE'', a long-established restaurant in Minato-gawa, Urasoe City, which has been in business for 60 years. The host, TOMA, is vaccinated against COVID-19. Visiting the location can be challenging for both locals and tourists, but you can enjoy the walking experience through this video. Join me in exploring Okinawa''s charm!' where id = '-ulnevH7Oz-GJW0bOKwol';
