update content_bodies set title = 'Exploring the Original Scenery of Okinawa #3: Kouri Island Edition, Nakijin Village #178 [4K] Okinawa Walk', description = 'In this video, we take a stroll through Kouri Island and Kouri Village in Nakijin Village. The beautiful island is covered by a blue sea and sky, showcasing the original scenery of Okinawa. The host, TOMA, has been vaccinated against COVID-19. Since visiting the location can be challenging for both local and non-local visitors, enjoy the walking experience through this video.' where id = '-gvTFmWIIuDWbTT9JO7Hx';
